BEGIN;

-- ============================================================
-- TEAM MEMORY: CONSOLIDATED DEVELOPMENT BASELINE RESET
--
-- Deletes existing Team Memory tables and their data, including documents/profiles.
-- ONE standalone setup script: includes all consolidated features as of 2026-11-06.
-- Intended only for a fresh/disposable LOCAL development database.
-- Never run against an existing hosted project or real team data. The non-destructive
-- hosted proposal is generated by backend/app/schema_upgrade.py for approval.
-- ============================================================

CREATE SCHEMA IF NOT EXISTS extensions;

CREATE EXTENSION IF NOT EXISTS vector
WITH SCHEMA extensions;

-- Fail clearly if an existing vector installation uses another schema.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_catalog.pg_extension AS e
        JOIN pg_catalog.pg_namespace AS n ON n.oid = e.extnamespace
        WHERE e.extname = 'vector' AND n.nspname = 'extensions'
    ) THEN
        RAISE EXCEPTION 'The vector extension must be installed in the extensions schema';
    END IF;
END;
$$;

-- Reset only the named project objects; dependencies are removed transactionally.
DO $reset$
DECLARE target text;
BEGIN
    FOR target IN
        SELECT p.oid::regprocedure::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
        WHERE n.nspname='public' AND p.proname=ANY(ARRAY['apply_commitment_action', 'apply_commitment_action_internal', 'apply_commitment_chat_action', 'begin_reminder_dispatch', 'claim_memory_embeddings', 'claim_reminder_deliveries', 'clear_stale_memory_embedding', 'commitment_reminder', 'commitment_snapshot', 'commitment_summary', 'create_owner_commitment', 'defer_reminder_delivery', 'document_operation', 'finish_memory_embedding', 'finish_reminder_delivery', 'invalidate_commitment_reminders', 'invalidate_policy_reminders', 'persist_reminder_intention', 'prepare_commitment_chat', 'read_commitment_lifecycle', 'read_reminder_dispatch', 'read_reminder_work', 'refresh_person_profile', 'refresh_profile_evidence', 'reminder_delivery_current', 'reminder_delivery_json', 'reminder_history_json', 'reminder_policy_json', 'reminder_quiet', 'reminder_record_eligible', 'reminder_work_json', 'search_memories', 'set_updated_at', 'store_message_extraction', 'store_profile_message_extraction', 'version_reminder_policy'])
    LOOP
        EXECUTE 'DROP FUNCTION IF EXISTS ' || target || ' CASCADE';
    END LOOP;
END;
$reset$;

-- Remove the previous search definition before resetting its source table.
DROP FUNCTION IF EXISTS public.search_memories(
    UUID, UUID, extensions.vector, INTEGER
);
DROP FUNCTION IF EXISTS public.store_message_extraction(UUID, TEXT, JSONB, JSONB);
DROP FUNCTION IF EXISTS public.claim_memory_embeddings(UUID, UUID[], INTEGER);
DROP FUNCTION IF EXISTS public.finish_memory_embedding(UUID, UUID, UUID, UUID, TEXT, extensions.vector, TEXT);

DROP TABLE IF EXISTS
    public.commitment_action_events,
    public.commitment_action_receipts,
    public.commitment_chat_identities,
    public.commitment_chat_policies,
    public.commitment_chat_sources,
    public.commitments,
    public.decisions,
    public.document_chunks,
    public.document_imports,
    public.document_versions,
    public.documents,
    public.memories,
    public.messages,
    public.person_profile_claims,
    public.person_profile_evidence,
    public.person_profiles,
    public.profile_extractions,
    public.reminder_deliveries,
    public.room_members,
    public.rooms,
    public.tenants CASCADE;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ============================================================
-- 1. TEAMS AND SWITCH ROOMS
-- ============================================================

CREATE TABLE public.tenants (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL CHECK (btrim(name) <> ''),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE public.rooms (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL
        REFERENCES public.tenants(id) ON DELETE RESTRICT,

    switch_room_id TEXT NOT NULL UNIQUE
        CHECK (btrim(switch_room_id) <> ''),

    name TEXT,
    platform TEXT
        CHECK (platform IN ('discord', 'slack', 'teams')),
    workspace_id TEXT,
    channel_id TEXT,

    enabled BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    UNIQUE (tenant_id, id)
);

-- Backend-managed room permissions.
-- Populate only from trusted onboarding or admin actions.
CREATE TABLE public.room_members (
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,
    switch_user_id TEXT NOT NULL
        CHECK (btrim(switch_user_id) <> ''),

    role TEXT NOT NULL DEFAULT 'member'
        CHECK (role IN ('member', 'approver', 'admin')),

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, room_id, switch_user_id),

    FOREIGN KEY (tenant_id, room_id)
        REFERENCES public.rooms(tenant_id, id)
        ON DELETE RESTRICT
);

-- ============================================================
-- 2. MESSAGES AND EXTRACTION PROCESSING
-- ============================================================

CREATE TABLE public.messages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,

    switch_message_id TEXT NOT NULL
        CHECK (btrim(switch_message_id) <> ''),
    switch_author_id TEXT,

    platform TEXT
        CHECK (platform IN ('discord', 'slack', 'teams')),
    workspace_id TEXT,
    channel_id TEXT,
    external_message_id TEXT,
    external_author_id TEXT,
    thread_id TEXT,

    author_name TEXT,
    body TEXT NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    extraction_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (
            extraction_status IN (
                'pending', 'processing', 'completed', 'failed'
            )
        ),

    extraction_attempts INTEGER NOT NULL DEFAULT 0
        CHECK (extraction_attempts >= 0),
    extraction_next_attempt_at TIMESTAMPTZ DEFAULT now(),
    extraction_lease_until TIMESTAMPTZ,
    extraction_claim_token UUID,
    extraction_completed_at TIMESTAMPTZ,

    -- Store sanitized error codes, never credentials or raw errors.
    extraction_error_code TEXT,

    FOREIGN KEY (tenant_id, room_id)
        REFERENCES public.rooms(tenant_id, id)
        ON DELETE RESTRICT,

    UNIQUE (tenant_id, room_id, switch_message_id),
    UNIQUE (tenant_id, room_id, id),

    CHECK (
        extraction_status <> 'completed'
        OR extraction_completed_at IS NOT NULL
    )
);

CREATE INDEX idx_messages_room_time
    ON public.messages (tenant_id, room_id, occurred_at DESC);

CREATE INDEX idx_messages_extraction_queue
    ON public.messages (extraction_next_attempt_at)
    WHERE extraction_status IN ('pending', 'failed');

CREATE INDEX idx_messages_extraction_lease
    ON public.messages (extraction_lease_until)
    WHERE extraction_status = 'processing';

-- Switch message IDs are the primary deduplication identity.
-- Original platform IDs are retained for evidence and lookups.
CREATE INDEX idx_messages_external_source
    ON public.messages (
        platform, workspace_id, channel_id, external_message_id
    );

-- ============================================================
-- 3. COMMITMENTS
-- ============================================================

CREATE TABLE public.commitments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,
    message_id UUID NOT NULL,

    -- Stable item key within a message's extraction result.
    extraction_key TEXT NOT NULL
        CHECK (btrim(extraction_key) <> ''),

    description TEXT NOT NULL,
    owner_name TEXT,
    owner_external_id TEXT,
    owner_switch_user_id TEXT,
    due_at TIMESTAMPTZ,

    approval_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (
            approval_status IN ('pending', 'approved', 'rejected')
        ),

    approval_by_switch_user_id TEXT,
    approval_at TIMESTAMPTZ,

    task_status TEXT NOT NULL DEFAULT 'not_started'
        CHECK (
            task_status IN (
                'not_started', 'in_progress', 'completed', 'cancelled'
            )
        ),

    completed_at TIMESTAMPTZ,
    next_reminder_at TIMESTAMPTZ,
    last_chased_at TIMESTAMPTZ,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    FOREIGN KEY (tenant_id, room_id, message_id)
        REFERENCES public.messages(tenant_id, room_id, id)
        ON DELETE RESTRICT,

    UNIQUE (message_id, extraction_key),
    UNIQUE (tenant_id, room_id, id),

    CHECK (
        (task_status = 'completed' AND completed_at IS NOT NULL)
        OR
        (task_status <> 'completed' AND completed_at IS NULL)
    ),

    CHECK (
        approval_status = 'pending'
        OR (
            approval_by_switch_user_id IS NOT NULL
            AND approval_at IS NOT NULL
        )
    )
);

CREATE INDEX idx_commitments_room_created
    ON public.commitments (tenant_id, room_id, created_at DESC);

CREATE INDEX idx_commitments_message
    ON public.commitments (tenant_id, room_id, message_id);

CREATE INDEX idx_commitments_owner
    ON public.commitments (
        tenant_id, room_id, owner_switch_user_id
    );

CREATE INDEX idx_commitments_reminder_queue
    ON public.commitments (next_reminder_at)
    WHERE approval_status = 'approved'
      AND task_status IN ('not_started', 'in_progress');

-- ============================================================
-- 4. DECISIONS
-- ============================================================

CREATE TABLE public.decisions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,
    message_id UUID NOT NULL,

    extraction_key TEXT NOT NULL
        CHECK (btrim(extraction_key) <> ''),

    topic TEXT,
    summary TEXT NOT NULL,

    approval_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (
            approval_status IN ('pending', 'approved', 'rejected')
        ),

    approval_by_switch_user_id TEXT,
    approval_at TIMESTAMPTZ,

    decision_status TEXT NOT NULL DEFAULT 'active'
        CHECK (
            decision_status IN ('active', 'superseded', 'revoked')
        ),

    supersedes_decision_id UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    UNIQUE (message_id, extraction_key),
    UNIQUE (tenant_id, room_id, id),

    FOREIGN KEY (tenant_id, room_id, message_id)
        REFERENCES public.messages(tenant_id, room_id, id)
        ON DELETE RESTRICT,

    FOREIGN KEY (tenant_id, room_id, supersedes_decision_id)
        REFERENCES public.decisions(tenant_id, room_id, id)
        ON DELETE RESTRICT,

    CHECK (
        supersedes_decision_id IS NULL
        OR supersedes_decision_id <> id
    ),

    CHECK (
        approval_status = 'pending'
        OR (
            approval_by_switch_user_id IS NOT NULL
            AND approval_at IS NOT NULL
        )
    )
);

CREATE INDEX idx_decisions_room_created
    ON public.decisions (tenant_id, room_id, created_at DESC);

CREATE INDEX idx_decisions_message
    ON public.decisions (tenant_id, room_id, message_id);

CREATE INDEX idx_decisions_supersedes
    ON public.decisions (
        tenant_id, room_id, supersedes_decision_id
    )
    WHERE supersedes_decision_id IS NOT NULL;

-- ============================================================
-- VECTOR MEMORY STORAGE
-- ============================================================

-- Searchable facts and summaries retain their original message evidence.
-- Commitment deadlines/status remain in commitments.
-- Decision approval/status remain in decisions.
-- FastAPI must synchronize these summaries with their structured records.
CREATE TABLE public.memories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL,
    room_id UUID NOT NULL,
    message_id UUID NOT NULL,

    memory_type TEXT NOT NULL
        CHECK (memory_type IN ('fact', 'decision', 'commitment')),
    extraction_key TEXT NOT NULL
        CHECK (btrim(extraction_key) <> ''),
    content TEXT NOT NULL CHECK (btrim(content) <> ''),

    -- Generate embeddings in the backend, using the same model for queries.
    -- NULL embeddings are allowed while generation is pending.
    embedding extensions.vector(384),
    embedding_model TEXT NOT NULL DEFAULT 'Supabase/gte-small'
        CHECK (embedding_model = 'Supabase/gte-small'),
    -- EMBEDDING_COLUMNS_BEGIN
    content_hash TEXT NOT NULL,
    embedding_recipe TEXT NOT NULL DEFAULT '93b36ff09519291b77d6000d2e86bd8565378086:onnx-fp32:masked-mean:l2:v1'
        CHECK (embedding_recipe = '93b36ff09519291b77d6000d2e86bd8565378086:onnx-fp32:masked-mean:l2:v1'),
    embedding_content_hash TEXT,
    embedding_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (embedding_status IN ('pending','processing','completed','failed')),
    embedding_attempts INTEGER NOT NULL DEFAULT 0 CHECK (embedding_attempts >= 0),
    embedding_next_attempt_at TIMESTAMPTZ DEFAULT now(),
    embedding_lease_until TIMESTAMPTZ,
    embedding_claim_token UUID,
    embedding_completed_at TIMESTAMPTZ,
    embedding_error_code TEXT,
    -- EMBEDDING_COLUMNS_END

    active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    FOREIGN KEY (tenant_id, room_id, message_id)
        REFERENCES public.messages(tenant_id, room_id, id)
        ON DELETE RESTRICT,

    UNIQUE (message_id, memory_type, extraction_key),
    CONSTRAINT memories_embedding_state_check CHECK ((embedding_status = 'completed') = (embedding IS NOT NULL)),
    CONSTRAINT memories_embedding_content_check CHECK (embedding_status <> 'completed' OR (
        embedding_content_hash = content_hash AND embedding_content_hash IS NOT NULL
        AND embedding_completed_at IS NOT NULL
        AND extensions.vector_norm(embedding) > 0))
);

CREATE INDEX idx_memories_room
    ON public.memories (tenant_id, room_id);

CREATE INDEX idx_memories_source_message
    ON public.memories (tenant_id, room_id, message_id);
CREATE INDEX idx_memories_embedding_queue
    ON public.memories (tenant_id, room_id, embedding_next_attempt_at)
    WHERE active AND embedding_status IN ('pending','failed');
CREATE INDEX idx_memories_embedding_lease
    ON public.memories (embedding_lease_until)
    WHERE embedding_status = 'processing';

-- An edited memory must not be searched using its previous text's embedding.
-- The backend regenerates the embedding after updating content.
CREATE OR REPLACE FUNCTION public.clear_stale_memory_embedding()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
BEGIN
    NEW.content_hash = pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(NEW.content, 'UTF8')), 'hex');
    IF TG_OP = 'INSERT' THEN
        IF NEW.embedding IS NOT NULL THEN
            NEW.embedding_status = 'completed';
            NEW.embedding_content_hash = NEW.content_hash;
            NEW.embedding_completed_at = now();
        END IF;
    ELSIF NEW.content IS DISTINCT FROM OLD.content THEN
        NEW.embedding = NULL;
        NEW.embedding_content_hash = NULL;
        NEW.embedding_status = 'pending';
        NEW.embedding_attempts = 0;
        NEW.embedding_next_attempt_at = now();
        NEW.embedding_lease_until = NULL;
        NEW.embedding_claim_token = NULL;
        NEW.embedding_completed_at = NULL;
        NEW.embedding_error_code = NULL;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER memories_clear_stale_embedding
BEFORE INSERT OR UPDATE OF content ON public.memories
FOR EACH ROW EXECUTE FUNCTION public.clear_stale_memory_embedding();

-- Exact vector search is sufficient for the initial small dataset.
-- Add an approximate vector index only after measuring search performance.
CREATE FUNCTION public.search_memories(
    p_tenant_id UUID,
    p_room_id UUID,
    p_embedding extensions.vector(384),
    p_limit INTEGER DEFAULT 5
)
RETURNS TABLE (
    id UUID,
    message_id UUID,
    memory_type TEXT,
    content TEXT,
    similarity DOUBLE PRECISION
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
    SELECT
        m.id,
        m.message_id,
        m.memory_type,
        m.content,
        1 - (
            m.embedding OPERATOR(extensions.<=>) p_embedding
        ) AS similarity
    FROM public.memories AS m
    WHERE p_embedding IS NOT NULL
      AND m.tenant_id = p_tenant_id
      AND m.room_id = p_room_id
      AND m.active = true
      AND m.embedding IS NOT NULL
      AND m.embedding_status = 'completed'
      AND m.embedding_content_hash = m.content_hash
      AND m.embedding_recipe = '93b36ff09519291b77d6000d2e86bd8565378086:onnx-fp32:masked-mean:l2:v1'
    ORDER BY
        m.embedding OPERATOR(extensions.<=>) p_embedding
    LIMIT greatest(1, least(coalesce(p_limit, 5), 50));
$$;

-- ATOMIC_STORAGE_BEGIN
CREATE FUNCTION public.store_message_extraction(
    p_tenant_id uuid, p_switch_room_id text, p_source jsonb, p_items jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE
    room_uuid uuid;
    message_uuid uuid;
    existing_status text;
    item jsonb;
    counts jsonb;
BEGIN
    SELECT id INTO room_uuid FROM public.rooms
    WHERE tenant_id = p_tenant_id AND switch_room_id = p_switch_room_id AND enabled
    FOR SHARE;
    IF room_uuid IS NULL THEN
        RAISE EXCEPTION 'unauthorized_room' USING ERRCODE = '42501';
    END IF;
    IF nullif(btrim(p_source->>'switch_message_id'), '') IS NULL
       OR jsonb_typeof(p_items->'commitments') IS DISTINCT FROM 'array'
       OR jsonb_typeof(p_items->'decisions') IS DISTINCT FROM 'array'
       OR jsonb_typeof(p_items->'memories') IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_items->'memories') = 0 THEN
        RAISE EXCEPTION 'invalid_extraction' USING ERRCODE = '22023';
    END IF;
    -- Serialize replays even across API hosts; hash collisions only serialize extra work.
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_tenant_id::text || ':' || room_uuid::text || ':' || (p_source->>'switch_message_id'), 0));
    SELECT id, extraction_status INTO message_uuid, existing_status
    FROM public.messages WHERE tenant_id = p_tenant_id AND room_id = room_uuid
      AND switch_message_id = p_source->>'switch_message_id' FOR UPDATE;

    IF existing_status IS DISTINCT FROM 'completed' THEN
        IF message_uuid IS NULL THEN
            INSERT INTO public.messages (
                tenant_id, room_id, switch_message_id, switch_author_id, platform,
                workspace_id, channel_id, external_message_id, external_author_id,
                thread_id, author_name, body, occurred_at
            ) VALUES (
                p_tenant_id, room_uuid, p_source->>'switch_message_id', p_source->>'switch_author_id',
                p_source->>'platform', p_source->>'workspace_id', p_source->>'channel_id',
                p_source->>'external_message_id', p_source->>'external_author_id',
                p_source->>'thread_id', p_source->>'author_name', p_source->>'body',
                (p_source->>'occurred_at')::timestamptz
            ) RETURNING id INTO message_uuid;
        END IF;
        FOR item IN SELECT value FROM jsonb_array_elements(p_items->'commitments') LOOP
            INSERT INTO public.commitments (tenant_id, room_id, message_id, extraction_key,
                                           description, owner_name, due_at)
            VALUES (p_tenant_id, room_uuid, message_uuid, item->>'extraction_key',
                    item->>'description', item->>'owner_name', (item->>'due_at')::timestamptz)
            ON CONFLICT (message_id, extraction_key) DO NOTHING;
        END LOOP;
        FOR item IN SELECT value FROM jsonb_array_elements(p_items->'decisions') LOOP
            INSERT INTO public.decisions (tenant_id, room_id, message_id, extraction_key, topic, summary)
            VALUES (p_tenant_id, room_uuid, message_uuid, item->>'extraction_key', item->>'topic', item->>'summary')
            ON CONFLICT (message_id, extraction_key) DO NOTHING;
        END LOOP;
        FOR item IN SELECT value FROM jsonb_array_elements(p_items->'memories') LOOP
            INSERT INTO public.memories (tenant_id, room_id, message_id, extraction_key, memory_type, content)
            VALUES (p_tenant_id, room_uuid, message_uuid, item->>'extraction_key', item->>'memory_type', item->>'content')
            ON CONFLICT (message_id, memory_type, extraction_key) DO NOTHING;
        END LOOP;
        UPDATE public.messages SET extraction_status = 'completed', extraction_completed_at = now(),
            extraction_error_code = NULL, extraction_lease_until = NULL, extraction_claim_token = NULL
        WHERE id = message_uuid;
    END IF;
    SELECT jsonb_build_object(
        'messages', 1,
        'commitments', (SELECT count(*) FROM public.commitments WHERE message_id = message_uuid),
        'decisions', (SELECT count(*) FROM public.decisions WHERE message_id = message_uuid),
        'memories', (SELECT count(*) FROM public.memories WHERE message_id = message_uuid)
    ) INTO counts;
    RETURN counts;
END;
$$;

REVOKE ALL ON FUNCTION public.store_message_extraction(uuid,text,jsonb,jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.store_message_extraction(uuid,text,jsonb,jsonb) TO service_role;
-- ATOMIC_STORAGE_END

-- EMBEDDING_WORK_BEGIN
-- Memory rows themselves are durable, versioned embedding jobs. Claim leases recover
-- after a process crash; claim tokens + hashes prevent stale results after edits.
CREATE FUNCTION public.claim_memory_embeddings(
    p_tenant_id UUID, p_room_ids UUID[], p_limit INTEGER DEFAULT 8
) RETURNS TABLE (
    id UUID, tenant_id UUID, room_id UUID, message_id UUID,
    content TEXT, content_hash TEXT, claim_token UUID
)
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
BEGIN
    UPDATE public.memories AS m SET embedding_status='failed',
        embedding_error_code='lease_exhausted', embedding_lease_until=NULL, embedding_claim_token=NULL
    WHERE m.tenant_id=p_tenant_id AND m.room_id=ANY(p_room_ids)
      AND m.embedding_status='processing' AND m.embedding_attempts>=3
      AND m.embedding_lease_until<=now();
    RETURN QUERY
    WITH candidates AS (
        SELECT m.id FROM public.memories AS m
        JOIN public.rooms AS r ON r.id=m.room_id AND r.tenant_id=m.tenant_id AND r.enabled
        WHERE m.tenant_id=p_tenant_id AND m.room_id=ANY(p_room_ids) AND m.active
          AND m.embedding_attempts<3
          AND ((m.embedding_status IN ('pending','failed') AND m.embedding_next_attempt_at<=now())
               OR (m.embedding_status='processing' AND m.embedding_lease_until<=now()))
        ORDER BY m.created_at,m.id
        LIMIT greatest(1,least(coalesce(p_limit,8),8)) FOR UPDATE OF m SKIP LOCKED
    )
    UPDATE public.memories AS m SET embedding_status='processing',
        embedding_attempts=m.embedding_attempts+1,
        embedding_lease_until=now()+interval '5 minutes', embedding_claim_token=gen_random_uuid(),
        embedding_error_code=NULL
    FROM candidates AS c WHERE m.id=c.id
    RETURNING m.id,m.tenant_id,m.room_id,m.message_id,m.content,m.content_hash,m.embedding_claim_token;
END;
$$;

CREATE FUNCTION public.finish_memory_embedding(
    p_memory_id UUID, p_tenant_id UUID, p_room_id UUID, p_claim_token UUID,
    p_content_hash TEXT, p_embedding extensions.vector(384), p_error_code TEXT DEFAULT NULL
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE changed INTEGER;
BEGIN
    IF p_error_code IS NOT NULL THEN
        IF p_error_code NOT IN ('input_too_long','invalid_input','invalid_vector','model_not_installed',
            'model_checksum_failed','dependencies_missing','inference_failed','worker_interrupted') THEN
            RAISE EXCEPTION 'invalid_embedding_error' USING ERRCODE='22023';
        END IF;
    ELSIF p_embedding IS NULL OR extensions.vector_dims(p_embedding)<>384
        OR abs(extensions.vector_norm(p_embedding)-1)>0.001
        OR NOT (extensions.vector_norm(p_embedding)>0) THEN
        RAISE EXCEPTION 'invalid_embedding_vector' USING ERRCODE='22023';
    END IF;
    UPDATE public.memories AS m SET
        embedding=CASE WHEN p_error_code IS NULL THEN p_embedding ELSE NULL END,
        embedding_content_hash=CASE WHEN p_error_code IS NULL THEN p_content_hash ELSE NULL END,
        embedding_status=CASE WHEN p_error_code IS NULL THEN 'completed' ELSE 'failed' END,
        embedding_completed_at=CASE WHEN p_error_code IS NULL THEN now() ELSE NULL END,
        embedding_error_code=p_error_code,
        embedding_attempts=CASE WHEN p_error_code IN ('input_too_long','invalid_input') THEN 3 ELSE m.embedding_attempts END,
        embedding_next_attempt_at=CASE WHEN p_error_code IS NULL THEN NULL ELSE now()+interval '30 seconds' END,
        embedding_lease_until=NULL, embedding_claim_token=NULL
    WHERE m.id=p_memory_id AND m.tenant_id=p_tenant_id AND m.room_id=p_room_id
      AND m.content_hash=p_content_hash AND m.embedding_claim_token=p_claim_token
      AND m.embedding_status='processing'
      AND EXISTS (SELECT 1 FROM public.rooms AS r WHERE r.id=m.room_id AND r.tenant_id=m.tenant_id AND r.enabled);
    GET DIAGNOSTICS changed = ROW_COUNT;
    RETURN changed=1;
END;
$$;

REVOKE ALL ON FUNCTION public.claim_memory_embeddings(UUID,UUID[],INTEGER) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.finish_memory_embedding(UUID,UUID,UUID,UUID,TEXT,extensions.vector,TEXT) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_memory_embeddings(UUID,UUID[],INTEGER) TO service_role;
GRANT EXECUTE ON FUNCTION public.finish_memory_embedding(UUID,UUID,UUID,UUID,TEXT,extensions.vector,TEXT) TO service_role;
