-- Additive document module. Never replay the destructive core baseline remotely.

CREATE TABLE public.documents (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    source_key text NOT NULL CHECK (length(source_key) BETWEEN 1 AND 200),
    source_type text NOT NULL CHECK (source_type IN ('markdown','text','pdf','docx','pptx')),
    title text NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
    created_by text NOT NULL,
    latest_version integer NOT NULL DEFAULT 0 CHECK (latest_version >= 0),
    published_version_id uuid,
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id,room_id,source_key),
    UNIQUE (tenant_id,room_id,id),
    FOREIGN KEY (tenant_id,room_id) REFERENCES public.rooms(tenant_id,id) ON DELETE RESTRICT
);
CREATE TABLE public.document_versions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    document_id uuid NOT NULL,
    version_number integer NOT NULL CHECK (version_number > 0),
    title text NOT NULL,
    filename text NOT NULL,
    source_text text NOT NULL CHECK (octet_length(source_text) BETWEEN 1 AND 262144),
    content_hash text NOT NULL CHECK (content_hash = encode(sha256(convert_to(source_text,'UTF8')),'hex')),
    recipe text NOT NULL,
    model_recipe text NOT NULL,
    status text NOT NULL DEFAULT 'processing' CHECK (status IN ('processing','completed','failed')),
    error text CHECK (error IN ('model_not_installed','model_checksum_failed','dependencies_missing',
        'invalid_vector','invalid_input','input_too_long','inference_failed','lease_exhausted','version_superseded')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (document_id,version_number),
    UNIQUE (tenant_id,room_id,document_id,id),
    FOREIGN KEY (tenant_id,room_id,document_id) REFERENCES public.documents(tenant_id,room_id,id) ON DELETE RESTRICT
);
ALTER TABLE public.documents ADD CONSTRAINT documents_published_version_fk
    FOREIGN KEY (tenant_id,room_id,id,published_version_id)
    REFERENCES public.document_versions(tenant_id,room_id,document_id,id) ON DELETE RESTRICT;
CREATE TABLE public.document_chunks (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    document_id uuid NOT NULL,
    version_id uuid NOT NULL,
    position integer NOT NULL CHECK (position >= 0),
    text text NOT NULL CHECK (length(text)>0),
    content_hash text NOT NULL CHECK (content_hash=encode(sha256(convert_to(text,'UTF8')),'hex')),
    start_char integer NOT NULL CHECK (start_char>=0),
    end_char integer NOT NULL CHECK (end_char>start_char),
    start_line integer NOT NULL CHECK (start_line>0),
    end_line integer NOT NULL CHECK (end_line>=start_line),
    section text,
    model_recipe text NOT NULL,
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','failed')),
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 3),
    error text CHECK (error IN ('model_not_installed','model_checksum_failed','dependencies_missing',
        'invalid_vector','invalid_input','input_too_long','inference_failed','lease_exhausted','version_superseded')),
    retry_at timestamptz NOT NULL DEFAULT now(),
    lease_until timestamptz,
    claim_token uuid,
    embedding extensions.vector(384),
    embedding_content_hash text,
    CHECK ((status='completed') = (embedding IS NOT NULL)),
    CHECK (status<>'completed' OR embedding_content_hash IS NOT DISTINCT FROM content_hash),
    UNIQUE (version_id,position),
    FOREIGN KEY (tenant_id,room_id,document_id,version_id)
        REFERENCES public.document_versions(tenant_id,room_id,document_id,id) ON DELETE RESTRICT
);
CREATE TABLE public.document_imports (
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    import_id uuid NOT NULL,
    document_id uuid NOT NULL,
    version_id uuid NOT NULL,
    request_hash text NOT NULL,
    PRIMARY KEY (tenant_id,import_id),
    FOREIGN KEY (tenant_id,room_id,document_id,version_id)
        REFERENCES public.document_versions(tenant_id,room_id,document_id,id) ON DELETE RESTRICT
);
CREATE INDEX document_chunks_queue ON public.document_chunks(retry_at)
    WHERE status IN ('pending','failed');
CREATE INDEX document_chunks_lease ON public.document_chunks(lease_until) WHERE status='processing';
CREATE INDEX document_chunks_scope ON public.document_chunks(tenant_id,room_id,version_id);
-- Exact cosine search for the bounded initial corpus. No unbenchmarked ANN claim.
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_chunks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_imports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.documents,public.document_versions,public.document_chunks,public.document_imports FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.documents,public.document_versions,public.document_chunks,public.document_imports TO service_role;

CREATE FUNCTION public.document_operation(p_tenant_id uuid,p_room_ids uuid[],p_operation text,p_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,extensions AS $$
DECLARE
    d public.documents%ROWTYPE;
    v public.document_versions%ROWTYPE;
    c public.document_chunks%ROWTYPE;
    prior public.document_imports%ROWTYPE;
    piece jsonb;
    result jsonb;
    duplicate boolean := false;
    document_uuid uuid;
    vector_value extensions.vector(384);
    error_value text;
BEGIN
    IF p_tenant_id IS NULL OR coalesce(cardinality(p_room_ids),0)=0 OR
        EXISTS (SELECT 1 FROM unnest(p_room_ids) room WHERE NOT EXISTS (
            SELECT 1 FROM public.rooms r WHERE r.id=room AND r.tenant_id=p_tenant_id AND r.enabled)) THEN
        RAISE EXCEPTION 'document_scope_denied' USING ERRCODE='42501';
    END IF;
    IF p_operation='import_status' THEN
        SELECT * INTO prior FROM public.document_imports WHERE tenant_id=p_tenant_id AND room_id=ANY(p_room_ids)
            AND import_id=(p_data->>'import_id')::uuid;
        IF NOT FOUND THEN RAISE EXCEPTION 'document_not_found' USING ERRCODE='P0002'; END IF;
        SELECT * INTO v FROM public.document_versions WHERE id=prior.version_id;
        RETURN jsonb_build_object('import_id',prior.import_id,'document_id',prior.document_id,'version_id',v.id,
            'version_number',v.version_number,'status',v.status,'duplicate',true);
    ELSIF p_operation='import' THEN
        -- Serialize both idempotency identity and stable source identity, in fixed order.
        PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||(p_data->>'import_id'),0));
        PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||(p_data->>'room_id')||':'||(p_data->>'source_key'),1));
        SELECT * INTO prior FROM public.document_imports WHERE tenant_id=p_tenant_id AND import_id=(p_data->>'import_id')::uuid;
        IF FOUND THEN
            IF prior.request_hash<>p_data->>'request_hash' THEN
                RAISE EXCEPTION 'document_version_conflict' USING ERRCODE='40001';
            END IF;
            IF NOT prior.room_id=ANY(p_room_ids) THEN RAISE EXCEPTION 'document_scope_denied' USING ERRCODE='42501'; END IF;
            SELECT * INTO d FROM public.documents WHERE id=prior.document_id;
            SELECT * INTO v FROM public.document_versions WHERE id=prior.version_id;
            duplicate:=true;
        ELSE
            IF NOT (p_data->>'room_id')::uuid=ANY(p_room_ids) OR jsonb_array_length(p_data->'chunks') NOT BETWEEN 1 AND 1024 THEN
                RAISE EXCEPTION 'document_invalid_import' USING ERRCODE='22023';
            END IF;
            SELECT * INTO d FROM public.documents WHERE tenant_id=p_tenant_id AND room_id=(p_data->>'room_id')::uuid
                AND source_key=p_data->>'source_key' FOR UPDATE;
            IF coalesce(d.latest_version,0)<>(p_data->>'expected_version')::integer OR d.active=false
                OR (d.id IS NOT NULL AND d.source_type<>p_data->>'source_type') THEN
                RAISE EXCEPTION 'document_version_conflict' USING ERRCODE='40001';
            END IF;
            IF d.id IS NULL THEN
                INSERT INTO public.documents(tenant_id,room_id,source_key,source_type,title,created_by)
                VALUES(p_tenant_id,(p_data->>'room_id')::uuid,p_data->>'source_key',p_data->>'source_type',p_data->>'title',p_data->>'actor') RETURNING * INTO d;
            END IF;
            SELECT * INTO v FROM public.document_versions WHERE document_id=d.id AND version_number=d.latest_version;
            duplicate:=v.id IS NOT NULL AND v.content_hash=p_data->>'content_hash' AND v.recipe=p_data->>'recipe'
                AND v.model_recipe=p_data->>'model_recipe' AND v.title=p_data->>'title';
            IF NOT duplicate THEN
                UPDATE public.document_chunks x SET status='failed',error='version_superseded',claim_token=NULL,lease_until=NULL
                    FROM public.document_versions z WHERE x.version_id=z.id AND z.document_id=d.id AND z.status<>'completed'
                    AND x.status<>'completed';
                UPDATE public.document_versions SET status='failed',error='version_superseded'
                    WHERE document_id=d.id AND status<>'completed';
                INSERT INTO public.document_versions(tenant_id,room_id,document_id,version_number,title,filename,source_text,content_hash,recipe,model_recipe)
                VALUES(p_tenant_id,d.room_id,d.id,d.latest_version+1,p_data->>'title',p_data->>'filename',p_data->>'source_text',
                    p_data->>'content_hash',p_data->>'recipe',p_data->>'model_recipe') RETURNING * INTO v;
                FOR piece IN SELECT value FROM jsonb_array_elements(p_data->'chunks') LOOP
                    -- Locations must describe an exact slice of the preserved source.
                    IF substring(v.source_text FROM (piece->>'start_char')::integer+1
                        FOR (piece->>'end_char')::integer-(piece->>'start_char')::integer)<>piece->>'text' THEN
                        RAISE EXCEPTION 'document_invalid_chunk' USING ERRCODE='22023';
                    END IF;
                    INSERT INTO public.document_chunks(tenant_id,room_id,document_id,version_id,position,text,content_hash,
                        start_char,end_char,start_line,end_line,section,model_recipe)
                    VALUES(p_tenant_id,d.room_id,d.id,v.id,(piece->>'position')::integer,piece->>'text',piece->>'content_hash',
                        (piece->>'start_char')::integer,(piece->>'end_char')::integer,(piece->>'start_line')::integer,
                        (piece->>'end_line')::integer,piece->>'section',v.model_recipe);
                END LOOP;
                UPDATE public.documents SET latest_version=v.version_number WHERE id=d.id RETURNING * INTO d;
            END IF;
            INSERT INTO public.document_imports VALUES(p_tenant_id,d.room_id,(p_data->>'import_id')::uuid,d.id,v.id,p_data->>'request_hash');
        END IF;
        RETURN jsonb_build_object('import_id',p_data->>'import_id','document_id',d.id,'version_id',v.id,
            'version_number',v.version_number,'status',v.status,'duplicate',duplicate);
    ELSIF p_operation='documents' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') INTO result FROM (
            SELECT * FROM public.documents WHERE tenant_id=p_tenant_id AND room_id=ANY(p_room_ids)
            ORDER BY id LIMIT least(greatest((p_data->>'limit')::integer,1),50) OFFSET least(greatest((p_data->>'offset')::integer,0),10000)) q;
        RETURN result;
    ELSIF p_operation='claim' THEN
        -- Lock documents before chunks, just as finish/import/archive do.
        FOR d IN SELECT * FROM public.documents WHERE tenant_id=p_tenant_id AND room_id=ANY(p_room_ids) AND active
            ORDER BY id FOR UPDATE SKIP LOCKED LOOP
            UPDATE public.document_chunks x SET status='failed',error='lease_exhausted',claim_token=NULL
                FROM public.document_versions z WHERE x.version_id=z.id AND z.document_id=d.id AND z.version_number=d.latest_version
                AND x.status='processing' AND x.attempts>=3 AND x.lease_until<=now();
            UPDATE public.document_versions z SET status='failed',error='lease_exhausted' WHERE z.document_id=d.id
                AND z.version_number=d.latest_version AND EXISTS(SELECT 1 FROM public.document_chunks x WHERE x.version_id=z.id AND x.error='lease_exhausted');
        END LOOP;
        WITH picked AS (
            SELECT x.id FROM public.document_chunks x JOIN public.document_versions z ON z.id=x.version_id
            JOIN public.documents a ON a.id=x.document_id
            WHERE a.tenant_id=p_tenant_id AND a.room_id=ANY(p_room_ids) AND a.active
                AND z.version_number=a.latest_version AND x.attempts<3
                AND ((x.status IN ('pending','failed') AND x.retry_at<=now()) OR (x.status='processing' AND x.lease_until<=now()))
            ORDER BY x.id LIMIT 4 FOR UPDATE OF x SKIP LOCKED
        ), updated AS (
            UPDATE public.document_chunks x SET status='processing',attempts=x.attempts+1,claim_token=gen_random_uuid(),
                lease_until=now()+interval '5 minutes',error=NULL FROM picked WHERE x.id=picked.id RETURNING x.*
        ) SELECT coalesce(jsonb_agg(to_jsonb(updated)-'embedding'),'[]') INTO result FROM updated;
        RETURN result;
    ELSIF p_operation='finish' THEN
        SELECT document_id INTO document_uuid FROM public.document_chunks WHERE id=(p_data->>'id')::uuid
            AND tenant_id=p_tenant_id AND room_id=ANY(p_room_ids);
        IF document_uuid IS NULL THEN RETURN 'false'; END IF;
        SELECT * INTO d FROM public.documents WHERE id=document_uuid FOR UPDATE;
        SELECT * INTO c FROM public.document_chunks WHERE id=(p_data->>'id')::uuid FOR UPDATE;
        SELECT * INTO v FROM public.document_versions WHERE id=c.version_id;
        IF NOT d.active OR d.latest_version<>v.version_number OR c.status<>'processing' OR c.lease_until<=now()
            OR c.claim_token IS DISTINCT FROM (p_data->>'claim_token')::uuid OR c.content_hash<>p_data->>'content_hash'
            OR c.model_recipe<>p_data->>'model_recipe' THEN RETURN 'false'; END IF;
        error_value:=p_data->>'error';
        IF error_value IS NULL THEN
            vector_value:=(p_data->>'vector')::extensions.vector(384);
            IF vector_value IS NULL OR abs(extensions.vector_norm(vector_value)-1)>0.001 THEN
                RAISE EXCEPTION 'invalid_vector' USING ERRCODE='22023';
            END IF;
        ELSIF error_value NOT IN ('model_not_installed','model_checksum_failed','dependencies_missing',
            'invalid_vector','invalid_input','input_too_long','inference_failed') THEN
            RAISE EXCEPTION 'invalid_error' USING ERRCODE='22023';
        END IF;
        UPDATE public.document_chunks SET status=CASE WHEN error_value IS NULL THEN 'completed' ELSE 'failed' END,
            error=error_value,embedding=vector_value,embedding_content_hash=CASE WHEN error_value IS NULL THEN content_hash END,
            retry_at=now()+interval '30 seconds',claim_token=NULL,lease_until=NULL WHERE id=c.id;
        IF error_value IS NOT NULL AND c.attempts>=3 THEN
            UPDATE public.document_versions SET status='failed',error=error_value WHERE id=v.id;
        END IF;
        IF NOT EXISTS(SELECT 1 FROM public.document_chunks WHERE version_id=v.id AND status<>'completed') THEN
            UPDATE public.document_versions SET status='completed',error=NULL WHERE id=v.id;
            UPDATE public.documents SET published_version_id=v.id,title=v.title WHERE id=d.id;
        END IF;
        RETURN 'true';
    ELSIF p_operation='search' THEN
        vector_value:=(p_data->>'vector')::extensions.vector(384);
        IF vector_value IS NULL OR abs(extensions.vector_norm(vector_value)-1)>0.001 THEN RAISE EXCEPTION 'invalid_vector' USING ERRCODE='22023'; END IF;
        SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') INTO result FROM (
            SELECT a.id AS document_id,z.id AS version_id,z.version_number,x.id AS chunk_id,z.title,x.section,
                x.start_line,x.end_line,x.text,1-(x.embedding <=> vector_value) AS similarity
            FROM public.document_chunks x JOIN public.documents a ON a.id=x.document_id
            JOIN public.document_versions z ON z.id=x.version_id
            WHERE a.tenant_id=p_tenant_id AND a.room_id=ANY(p_room_ids) AND a.active
                AND a.published_version_id=z.id AND z.status='completed' AND x.status='completed'
                AND x.embedding_content_hash=x.content_hash AND x.model_recipe=p_data->>'model_recipe'
                AND (p_data->>'document_id' IS NULL OR a.id=(p_data->>'document_id')::uuid)
            ORDER BY x.embedding <=> vector_value,x.id LIMIT least(greatest((p_data->>'limit')::integer,1),20)
        ) q;
        RETURN result;
    END IF;
    SELECT * INTO d FROM public.documents WHERE id=(p_data->>'document_id')::uuid AND tenant_id=p_tenant_id
        AND room_id=ANY(p_room_ids) FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'document_not_found' USING ERRCODE='P0002'; END IF;
    IF p_operation='document' THEN RETURN to_jsonb(d);
    ELSIF p_operation='archive' THEN
        IF d.latest_version<>(p_data->>'expected_version')::integer THEN RAISE EXCEPTION 'document_version_conflict' USING ERRCODE='40001'; END IF;
        UPDATE public.documents SET active=false WHERE id=d.id RETURNING * INTO d;
        RETURN to_jsonb(d);
    ELSIF p_operation='versions' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') INTO result FROM (
            SELECT * FROM public.document_versions WHERE document_id=d.id ORDER BY version_number
            LIMIT least(greatest((p_data->>'limit')::integer,1),50) OFFSET least(greatest((p_data->>'offset')::integer,0),10000)) q;
        RETURN result;
    END IF;
    SELECT * INTO v FROM public.document_versions WHERE id=(p_data->>'version_id')::uuid AND document_id=d.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'document_not_found' USING ERRCODE='P0002'; END IF;
    IF p_operation='version' THEN RETURN to_jsonb(v);
    ELSIF p_operation='chunk' THEN
        SELECT * INTO c FROM public.document_chunks WHERE id=(p_data->>'chunk_id')::uuid AND version_id=v.id;
        IF NOT FOUND THEN RAISE EXCEPTION 'document_not_found' USING ERRCODE='P0002'; END IF;
        RETURN to_jsonb(c)-'embedding'-'claim_token';
    ELSIF p_operation='chunks' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(q)-'embedding'-'claim_token') ,'[]') INTO result FROM (
            SELECT * FROM public.document_chunks WHERE version_id=v.id ORDER BY position
            LIMIT least(greatest((p_data->>'limit')::integer,1),50) OFFSET least(greatest((p_data->>'offset')::integer,0),10000)) q;
        RETURN result;
    END IF;
    RAISE EXCEPTION 'document_invalid_operation' USING ERRCODE='22023';
END;
$$;
REVOKE ALL ON FUNCTION public.document_operation(uuid,uuid[],text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.document_operation(uuid,uuid[],text,jsonb) TO service_role;
NOTIFY pgrst,'reload schema';

-- Expect true. Function argument identity does not include vector dimensions.
SELECT to_regprocedure(
    'public.search_memories(uuid,uuid,extensions.vector,integer)'
) IS NOT NULL AS search_function_exists;

-- CONSOLIDATED_FEATURES_BEGIN

-- ============================================================
-- Consolidated from 20261105000100_commitment_lifecycle.sql
-- ============================================================
-- ADDITIVE PROPOSAL. Review before hosted deployment; never replay the core reset.
-- Requires the reviewed storage + embedding recovery baseline (or equivalent upgrades).

DO $$
BEGIN
    IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='memories'
        AND column_name IN ('content_hash','embedding_content_hash','embedding_status','embedding_claim_token','embedding_lease_until')) <> 5
      OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger
        WHERE tgrelid='public.memories'::regclass AND tgname='memories_clear_stale_embedding' AND NOT tgisinternal AND tgenabled <> 'D') THEN
      RAISE EXCEPTION 'commitment_lifecycle_requires_reviewed_embedding_recovery_upgrade';
    END IF;
END $$;
ALTER TABLE public.commitments ADD COLUMN version bigint NOT NULL DEFAULT 1 CHECK (version > 0);
ALTER TABLE public.commitments ADD COLUMN cancelled_at timestamptz;
ALTER TABLE public.commitments ADD CONSTRAINT commitments_cancelled_at_check
    CHECK (task_status = 'cancelled' OR cancelled_at IS NULL);
-- Existing unresolved/legacy identities are retained. Newly assigned identities are
-- checked under a membership lock by the RPC, without constraining AI extraction.

CREATE TABLE public.commitment_action_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
    tenant_id uuid NOT NULL, room_id uuid NOT NULL, commitment_id uuid NOT NULL,
    actor_id text NOT NULL CHECK (btrim(actor_id) <> ''),
    action text NOT NULL CHECK (action IN ('approve','reject','start','complete','cancel','reassign','reschedule')),
    occurred_at timestamptz NOT NULL,
    idempotency_key uuid NOT NULL, expected_version bigint NOT NULL CHECK (expected_version > 0),
    changed boolean NOT NULL, before jsonb NOT NULL, after jsonb NOT NULL,
    reason text CHECK (length(reason) <= 1000),
    FOREIGN KEY (tenant_id,room_id,commitment_id) REFERENCES public.commitments(tenant_id,room_id,id) ON DELETE RESTRICT
);
CREATE INDEX commitment_events_scope ON public.commitment_action_events(tenant_id,room_id,commitment_id,sequence);
CREATE TABLE public.commitment_action_receipts (
    tenant_id uuid NOT NULL, room_id uuid NOT NULL, actor_id text NOT NULL,
    idempotency_key uuid NOT NULL, commitment_id uuid NOT NULL,
    request jsonb NOT NULL, result jsonb NOT NULL,
    PRIMARY KEY (tenant_id,room_id,actor_id,idempotency_key),
    FOREIGN KEY (tenant_id,room_id,commitment_id) REFERENCES public.commitments(tenant_id,room_id,id) ON DELETE RESTRICT
);
ALTER TABLE public.commitment_action_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.commitment_action_receipts ENABLE ROW LEVEL SECURITY;
-- Override hosted default privileges too; GRANT alone would retain UPDATE/DELETE.
REVOKE ALL ON public.commitment_action_events, public.commitment_action_receipts FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT, INSERT ON public.commitment_action_events, public.commitment_action_receipts TO service_role;
REVOKE ALL ON SEQUENCE public.commitment_action_events_sequence_seq FROM PUBLIC, anon, authenticated, service_role;
GRANT USAGE, SELECT ON SEQUENCE public.commitment_action_events_sequence_seq TO service_role;

CREATE FUNCTION public.commitment_summary(c public.commitments) RETURNS text
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
    SELECT 'Commitment: ' || c.description || E'\nAssignee: ' ||
      coalesce(c.owner_switch_user_id, 'unresolved: ' || c.owner_name, 'unassigned') ||
      E'\nApproval: ' || c.approval_status || E'\nTask: ' || c.task_status ||
      E'\nDue (UTC): ' || coalesce(to_char(c.due_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'), 'unscheduled');
$$;
CREATE FUNCTION public.commitment_reminder(c public.commitments) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
    SELECT jsonb_build_object('eligible', reason = 'eligible', 'reason',reason,
                             'due_at',c.due_at,'assignee_id',c.owner_switch_user_id)
    FROM (SELECT CASE WHEN c.approval_status <> 'approved' THEN c.approval_status
        WHEN c.task_status IN ('completed','cancelled') THEN c.task_status
        WHEN c.owner_switch_user_id IS NULL THEN 'unassigned'
        WHEN c.due_at IS NULL THEN 'no_deadline' ELSE 'eligible' END reason) s;
$$;
CREATE FUNCTION public.commitment_snapshot(c public.commitments) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
    SELECT jsonb_build_object('approval_status',c.approval_status,'approval_by_switch_user_id',c.approval_by_switch_user_id,
      'approval_at',c.approval_at,'task_status',c.task_status,'owner_switch_user_id',c.owner_switch_user_id,
      'owner_name',c.owner_name,'due_at',c.due_at,'completed_at',c.completed_at,'cancelled_at',c.cancelled_at,
      'next_reminder_at',c.next_reminder_at,'version',c.version);
$$;

CREATE FUNCTION public.read_commitment_lifecycle(
    p_tenant_id uuid, p_room_id uuid, p_actor_id text, p_mode text,
    p_commitment_id uuid DEFAULT NULL, p_options jsonb DEFAULT '{}'
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE
    c public.commitments; member_role text; receipt public.commitment_action_receipts;
    result jsonb; page_limit integer; page_offset integer; total integer;
BEGIN
    SELECT m.role INTO member_role FROM public.room_members m JOIN public.rooms r
      ON r.tenant_id=m.tenant_id AND r.id=m.room_id
      WHERE m.tenant_id=p_tenant_id AND m.room_id=p_room_id AND m.switch_user_id=p_actor_id AND r.enabled;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404', MESSAGE='not_found'; END IF;
    IF p_mode <> 'list' THEN
      SELECT * INTO c FROM public.commitments WHERE tenant_id=p_tenant_id AND room_id=p_room_id AND id=p_commitment_id;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404', MESSAGE='not_found'; END IF;
    END IF;
    IF p_mode = 'context' THEN
      SELECT * INTO receipt FROM public.commitment_action_receipts WHERE tenant_id=p_tenant_id AND room_id=p_room_id
        AND actor_id=p_actor_id AND idempotency_key=(p_options->>'idempotency_key')::uuid;
      RETURN jsonb_build_object('commitment',to_jsonb(c),'role',member_role,
        'assignee_valid',EXISTS(SELECT 1 FROM public.room_members WHERE tenant_id=p_tenant_id AND room_id=p_room_id
             AND switch_user_id=p_options->>'assignee_id'),
        'previous_request',receipt.request,'previous_result',receipt.result);
    END IF;
    page_limit := coalesce((p_options->>'limit')::integer,25);
    page_offset := coalesce((p_options->>'offset')::integer,0);
    IF page_limit NOT BETWEEN 1 AND 100 OR page_offset NOT BETWEEN 0 AND 10000 THEN
      RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload';
    END IF;
    IF p_mode = 'list' THEN
      SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.created_at DESC,page.id DESC),'[]'::jsonb),count(*)
      INTO result,total FROM (
        SELECT * FROM public.commitments WHERE tenant_id=p_tenant_id AND room_id=p_room_id
          AND (p_options->>'approval_status' IS NULL OR approval_status=p_options->>'approval_status')
          AND (p_options->>'task_status' IS NULL OR task_status=p_options->>'task_status')
          AND (p_options->>'assignee_id' IS NULL OR owner_switch_user_id=p_options->>'assignee_id')
          AND (p_options->>'due_from' IS NULL OR due_at >= (p_options->>'due_from')::timestamptz)
          AND (p_options->>'due_to' IS NULL OR due_at <= (p_options->>'due_to')::timestamptz)
        ORDER BY created_at DESC,id DESC LIMIT page_limit+1 OFFSET page_offset
      ) page;
    ELSIF p_mode = 'history' THEN
      SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.sequence),'[]'::jsonb),count(*) INTO result,total FROM (
        SELECT * FROM public.commitment_action_events WHERE tenant_id=p_tenant_id AND room_id=p_room_id AND commitment_id=p_commitment_id
          ORDER BY sequence LIMIT page_limit+1 OFFSET page_offset
      ) page;
    ELSE RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload';
    END IF;
    IF total > page_limit THEN result := result - page_limit; END IF;
    RETURN jsonb_build_object('items',result,'next_offset',CASE WHEN total>page_limit THEN page_offset+page_limit END);
END;
$$;

CREATE FUNCTION public.apply_commitment_action(
    p_tenant_id uuid, p_room_id uuid, p_actor_id text, p_commitment_id uuid,
    p_action text, p_expected_version bigint, p_idempotency_key uuid, p_payload jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE
    c public.commitments; old_c public.commitments; member_role text;
    receipt public.commitment_action_receipts; event public.commitment_action_events;
    request_content jsonb; result jsonb; changed boolean := false;
    action_time timestamptz := transaction_timestamp(); new_due timestamptz;
BEGIN
    IF p_action IS NULL OR p_action NOT IN ('approve','reject','start','complete','cancel','reassign','reschedule')
      OR p_expected_version IS NULL OR p_expected_version < 1 OR p_idempotency_key IS NULL
      OR p_actor_id IS NULL OR btrim(p_actor_id) = '' OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
      OR (p_payload - 'reason' - CASE WHEN p_action='reassign' THEN 'assignee_id' WHEN p_action='reschedule' THEN 'due_at' ELSE 'reason' END) <> '{}'
      OR (p_payload->'reason' IS NOT NULL AND jsonb_typeof(p_payload->'reason') NOT IN ('string','null'))
      OR length(p_payload->>'reason') > 1000 THEN
      RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload';
    END IF;
    -- Serialize the same scoped key even if concurrent requests name different commitments.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::text || '/' || p_room_id::text || '/' || p_actor_id || '/' || p_idempotency_key::text,0));
    PERFORM 1 FROM public.rooms WHERE tenant_id=p_tenant_id AND id=p_room_id AND enabled FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404', MESSAGE='not_found'; END IF;
    SELECT role INTO member_role FROM public.room_members WHERE tenant_id=p_tenant_id AND room_id=p_room_id
      AND switch_user_id=p_actor_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404', MESSAGE='not_found'; END IF;
    SELECT * INTO c FROM public.commitments WHERE tenant_id=p_tenant_id AND room_id=p_room_id AND id=p_commitment_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404', MESSAGE='not_found'; END IF;
    IF (p_action IN ('approve','reject','cancel','reassign','reschedule') AND member_role NOT IN ('approver','admin'))
      OR (p_action IN ('start','complete') AND c.owner_switch_user_id IS DISTINCT FROM p_actor_id) THEN
      RAISE EXCEPTION USING ERRCODE='PT403', MESSAGE='forbidden_action';
    END IF;
    request_content := jsonb_build_object('commitment_id',p_commitment_id,'action',p_action,
                                         'expected_version',p_expected_version,'payload',p_payload);
    SELECT * INTO receipt FROM public.commitment_action_receipts WHERE tenant_id=p_tenant_id AND room_id=p_room_id
      AND actor_id=p_actor_id AND idempotency_key=p_idempotency_key;
    IF FOUND THEN
      IF receipt.request <> request_content THEN RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='idempotency_conflict'; END IF;
      RETURN receipt.result;
    END IF;
    IF c.version <> p_expected_version THEN RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='stale_version'; END IF;
    IF (c.task_status IN ('completed','cancelled') AND NOT (p_action='complete' AND c.task_status='completed')
        AND NOT (p_action='cancel' AND c.task_status='cancelled'))
      OR (c.approval_status='rejected' AND p_action <> 'reject') THEN
      RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='invalid_transition';
    END IF;
    old_c := c;
    CASE p_action
    WHEN 'approve' THEN
      IF c.approval_status='pending' THEN
        IF c.task_status <> 'not_started' THEN RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='invalid_transition'; END IF;
        c.approval_status:='approved'; c.approval_by_switch_user_id:=p_actor_id; c.approval_at:=action_time;
      END IF;
    WHEN 'reject' THEN
      IF c.approval_status NOT IN ('pending','rejected') OR c.task_status <> 'not_started' THEN
        RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='invalid_transition'; END IF;
      IF c.approval_status='pending' THEN
        c.approval_status:='rejected'; c.approval_by_switch_user_id:=p_actor_id; c.approval_at:=action_time;
      END IF;
    WHEN 'start','complete' THEN
      IF c.approval_status <> 'approved' THEN RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='invalid_transition'; END IF;
      IF p_action='start' THEN c.task_status:='in_progress';
      ELSE
        IF c.task_status <> 'completed' THEN c.completed_at:=action_time; END IF;
        c.task_status:='completed';
      END IF;
    WHEN 'cancel' THEN
      IF c.task_status <> 'cancelled' THEN c.task_status:='cancelled'; c.cancelled_at:=action_time; END IF;
    WHEN 'reassign' THEN
      IF jsonb_typeof(p_payload->'assignee_id') IS DISTINCT FROM 'string'
        OR length(p_payload->>'assignee_id') NOT BETWEEN 1 AND 512 OR (p_payload->>'assignee_id') ~ '\s' THEN
        RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_assignee'; END IF;
      PERFORM 1 FROM public.room_members WHERE tenant_id=p_tenant_id AND room_id=p_room_id
        AND switch_user_id=p_payload->>'assignee_id' FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_assignee'; END IF;
      IF c.owner_switch_user_id IS DISTINCT FROM p_payload->>'assignee_id' THEN
        c.owner_switch_user_id:=p_payload->>'assignee_id'; c.owner_name:=NULL;
      END IF;
    WHEN 'reschedule' THEN
      IF NOT (p_payload ? 'due_at') OR jsonb_typeof(p_payload->'due_at') NOT IN ('null','string') THEN
        RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload'; END IF;
      IF p_payload->>'due_at' IS NOT NULL THEN
        IF (p_payload->>'due_at') !~ '^\d{4}-\d{2}-\d{2}[Tt]\d{2}:\d{2}:\d{2}(\.\d+)?([Zz]|[+-]\d{2}:\d{2})$' THEN
          RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload'; END IF;
        BEGIN new_due:=(p_payload->>'due_at')::timestamptz;
        EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
          RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload'; END;
      END IF;
      c.due_at:=new_due;
    END CASE;
    changed := public.commitment_snapshot(c) <> public.commitment_snapshot(old_c);
    IF changed THEN
      UPDATE public.commitments SET approval_status=c.approval_status, approval_by_switch_user_id=c.approval_by_switch_user_id,
        approval_at=c.approval_at, task_status=c.task_status, completed_at=c.completed_at,cancelled_at=c.cancelled_at,
        owner_switch_user_id=c.owner_switch_user_id,owner_name=c.owner_name,due_at=c.due_at,
        next_reminder_at=NULL,version=version+1 WHERE id=c.id AND tenant_id=p_tenant_id AND room_id=p_room_id RETURNING * INTO c;
    END IF;
    -- Source message/extraction keys are immutable. Updating text invokes the existing
    -- embedding invalidation trigger, including clearing in-flight worker claims.
    INSERT INTO public.memories(tenant_id,room_id,message_id,memory_type,extraction_key,content,active)
      VALUES(c.tenant_id,c.room_id,c.message_id,'commitment',c.extraction_key,public.commitment_summary(c),
        c.approval_status <> 'rejected' AND c.task_status NOT IN ('completed','cancelled'))
      ON CONFLICT(message_id,memory_type,extraction_key) DO UPDATE SET content=EXCLUDED.content,active=EXCLUDED.active;
    INSERT INTO public.commitment_action_events(tenant_id,room_id,commitment_id,actor_id,action,occurred_at,
      idempotency_key,expected_version,changed,before,after,reason)
      VALUES(c.tenant_id,c.room_id,c.id,p_actor_id,p_action,action_time,p_idempotency_key,p_expected_version,changed,
        public.commitment_snapshot(old_c),public.commitment_snapshot(c),p_payload->>'reason') RETURNING * INTO event;
    result:=jsonb_build_object('commitment',to_jsonb(c),'reminder',public.commitment_reminder(c),'event',to_jsonb(event),'changed',changed);
    INSERT INTO public.commitment_action_receipts VALUES(p_tenant_id,p_room_id,p_actor_id,p_idempotency_key,c.id,request_content,result);
    RETURN result;
END;
$$;

-- Repair old searchable summaries without editing source evidence or lifecycle state.
UPDATE public.memories m SET content=public.commitment_summary(c),
    active=c.approval_status <> 'rejected' AND c.task_status NOT IN ('completed','cancelled')
FROM public.commitments c WHERE m.tenant_id=c.tenant_id AND m.room_id=c.room_id AND m.message_id=c.message_id
    AND m.memory_type='commitment' AND m.extraction_key=c.extraction_key;

REVOKE ALL ON FUNCTION public.commitment_summary(public.commitments),public.commitment_reminder(public.commitments),
  public.commitment_snapshot(public.commitments), public.read_commitment_lifecycle(uuid,uuid,text,text,uuid,jsonb),
  public.apply_commitment_action(uuid,uuid,text,uuid,text,bigint,uuid,jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.commitment_summary(public.commitments),public.commitment_reminder(public.commitments),
  public.commitment_snapshot(public.commitments), public.read_commitment_lifecycle(uuid,uuid,text,text,uuid,jsonb),
  public.apply_commitment_action(uuid,uuid,text,uuid,text,bigint,uuid,jsonb) TO service_role;

-- ============================================================
-- Consolidated from 20261105000200_commitment_chat.sql
-- ============================================================
-- Locally revised for open mentions. Hosted metadata lacks this module; migration
-- history/other environments are unverified. Do NOT replay an applied version.
-- Requires reviewed hosted reconciliation, not a reset or history rewrite.
-- Additive proposal; requires reviewed storage/embedding and commitment lifecycle.
-- Backend-only chat execution. Never apply the destructive core reset remotely.

CREATE TABLE public.commitment_chat_policies (
    tenant_id uuid NOT NULL,room_id uuid NOT NULL,
    enabled boolean NOT NULL DEFAULT false,
    timezone text CHECK(timezone IS NULL OR btrim(timezone) <> ''),
    accept_pending_owner_completion boolean NOT NULL DEFAULT false,
    handoff text NOT NULL DEFAULT 'admin_only' CHECK(handoff='admin_only'),
    PRIMARY KEY(tenant_id,room_id),
    FOREIGN KEY(tenant_id,room_id) REFERENCES public.rooms(tenant_id,id) ON DELETE RESTRICT
);
-- Trusted onboarding only. Names are matching hints; immutable sender tuples confer identity.
CREATE TABLE public.commitment_chat_identities (
    tenant_id uuid NOT NULL,room_id uuid NOT NULL,switch_author_id text NOT NULL CHECK(btrim(switch_author_id)<>''),
    external_author_id text NOT NULL DEFAULT '',
    subject_id text NOT NULL,label text CHECK(length(label)<=256),
    PRIMARY KEY(tenant_id,room_id,switch_author_id,external_author_id),
    FOREIGN KEY(tenant_id,room_id,subject_id) REFERENCES public.room_members(tenant_id,room_id,switch_user_id) ON DELETE CASCADE
);
CREATE TABLE public.commitment_chat_sources (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,room_id uuid NOT NULL,
    switch_message_id text NOT NULL,switch_author_id text NOT NULL,external_author_id text NOT NULL DEFAULT '',
    subject_id text NOT NULL,thread_id text,external_message_id text,workspace_id text,channel_id text,
    body text NOT NULL CHECK(length(body)<=64000),
    occurred_at timestamptz NOT NULL,source_input jsonb NOT NULL,policy_snapshot jsonb NOT NULL,
    UNIQUE(tenant_id,room_id,switch_message_id),UNIQUE(tenant_id,room_id,id),
    FOREIGN KEY(tenant_id,room_id) REFERENCES public.rooms(tenant_id,id) ON DELETE RESTRICT
);
ALTER TABLE public.commitments ADD COLUMN automated_acceptance_at timestamptz;
ALTER TABLE public.commitments ADD COLUMN automated_acceptance_source_id uuid;
ALTER TABLE public.commitments ADD COLUMN owner_accepted_at timestamptz;
ALTER TABLE public.commitments ADD COLUMN owner_acceptance_source_id uuid;
ALTER TABLE public.commitments ADD CONSTRAINT commitments_owner_acceptance_pair CHECK (
    (owner_accepted_at IS NULL) = (owner_acceptance_source_id IS NULL));
ALTER TABLE public.commitments ADD FOREIGN KEY(tenant_id,room_id,owner_acceptance_source_id)
    REFERENCES public.commitment_chat_sources(tenant_id,room_id,id) ON DELETE RESTRICT;
ALTER TABLE public.commitment_action_events DROP CONSTRAINT commitment_action_events_action_check;
ALTER TABLE public.commitment_action_events ADD CONSTRAINT commitment_action_events_action_check
    CHECK(action IN ('create','approve','reject','start','complete','cancel','reassign','reschedule'));
ALTER TABLE public.commitments ADD CONSTRAINT commitments_automated_acceptance_pair CHECK (
    (automated_acceptance_at IS NULL AND automated_acceptance_source_id IS NULL) OR
    (automated_acceptance_at IS NOT NULL AND automated_acceptance_source_id IS NOT NULL AND
        task_status='completed' AND approval_status='pending'));
ALTER TABLE public.commitments ADD FOREIGN KEY(tenant_id,room_id,automated_acceptance_source_id)
    REFERENCES public.commitment_chat_sources(tenant_id,room_id,id) ON DELETE RESTRICT;
ALTER TABLE public.commitment_action_events ADD COLUMN backend_actor text;
ALTER TABLE public.commitment_action_events ADD COLUMN source_evidence_id uuid;
ALTER TABLE public.commitment_action_events ADD COLUMN evidence text;
ALTER TABLE public.commitment_action_events ADD COLUMN outcome text NOT NULL DEFAULT 'applied' CHECK(outcome IN ('applied','no_change'));
-- Classify existing equivalent-action events in the newly added column only.
UPDATE public.commitment_action_events SET outcome='no_change' WHERE NOT changed;
ALTER TABLE public.commitment_action_events ADD CONSTRAINT commitment_chat_event_pair CHECK (
    (source_evidence_id IS NULL AND backend_actor IS NULL AND evidence IS NULL) OR
    (source_evidence_id IS NOT NULL AND backend_actor='switch-ingestion-worker' AND evidence IS NOT NULL));
ALTER TABLE public.commitment_action_events ADD FOREIGN KEY(tenant_id,room_id,source_evidence_id)
    REFERENCES public.commitment_chat_sources(tenant_id,room_id,id) ON DELETE RESTRICT;
CREATE UNIQUE INDEX commitment_chat_source_once ON public.commitment_action_events(source_evidence_id)
    WHERE source_evidence_id IS NOT NULL;
ALTER TABLE public.commitment_chat_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.commitment_chat_identities ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.commitment_chat_sources ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.commitment_chat_policies,public.commitment_chat_identities,public.commitment_chat_sources
    FROM PUBLIC,anon,authenticated,service_role;
-- Runtime cannot provision policies/identities, alter evidence or delete history.
GRANT SELECT ON public.commitment_chat_policies,public.commitment_chat_identities TO service_role;
-- Row sharing locks require UPDATE privilege on at least one column. The protected
-- touch column permits locking only; source input and identity columns stay immutable.
ALTER TABLE public.commitment_chat_policies ADD COLUMN lock_marker boolean NOT NULL DEFAULT false;
ALTER TABLE public.commitment_chat_identities ADD COLUMN lock_marker boolean NOT NULL DEFAULT false;
ALTER TABLE public.commitment_chat_sources ADD COLUMN lock_marker boolean NOT NULL DEFAULT false;
GRANT UPDATE(lock_marker) ON public.commitment_chat_policies,public.commitment_chat_identities,public.commitment_chat_sources TO service_role;
GRANT SELECT,INSERT ON public.commitment_chat_sources TO service_role;

CREATE FUNCTION public.prepare_commitment_chat(p_tenant_id uuid,p_switch_room_id text,p_source jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE
    room_uuid uuid; policy public.commitment_chat_policies; identity_row public.commitment_chat_identities;
    source_row public.commitment_chat_sources; actor_role text; candidates jsonb; members jsonb;
    open_mode boolean := p_source->>'policy_mode'='open_mentions'; policy_json jsonb;
BEGIN
    SELECT id INTO room_uuid FROM public.rooms WHERE tenant_id=p_tenant_id AND switch_room_id=p_switch_room_id AND enabled;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT * INTO policy FROM public.commitment_chat_policies WHERE tenant_id=p_tenant_id AND room_id=room_uuid AND enabled;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF coalesce(open_mode,false) THEN
      IF p_source->'sender_is_bot' IS DISTINCT FROM 'false'::jsonb
        OR nullif(p_source->>'switch_author_id','') IS NULL
        OR nullif(p_source->>'registered_agent_id','') IS NULL
        OR nullif(p_source->>'registered_agent_name','') IS NULL THEN RETURN NULL; END IF;
      -- Automatic participation projection, no onboarding or privileged authority.
      -- Platform is Switch's immutable puppet namespace; never join by display name.
      identity_row.subject_id := 'openchat:'||encode(sha256(convert_to(
        jsonb_build_array(p_tenant_id::text,room_uuid::text,'switch',p_source->>'switch_author_id')::text,'UTF8')),'hex');
      identity_row.switch_author_id:=p_source->>'switch_author_id';
      identity_row.external_author_id:=coalesce(p_source->>'external_author_id','');
      INSERT INTO public.room_members(tenant_id,room_id,switch_user_id,role)
        VALUES(p_tenant_id,room_uuid,identity_row.subject_id,'member') ON CONFLICT DO NOTHING;
      actor_role:='member'; -- Open chat never inherits admin or approver overrides.
    ELSE
    SELECT i.* INTO identity_row FROM public.commitment_chat_identities i
      WHERE i.tenant_id=p_tenant_id AND i.room_id=room_uuid AND i.switch_author_id=p_source->>'switch_author_id'
        AND i.external_author_id=coalesce(p_source->>'external_author_id','');
    IF NOT FOUND THEN RETURN NULL; END IF;
    END IF;
    policy_json:=jsonb_build_object('timezone',policy.timezone,'handoff',policy.handoff,
      'accept_pending_owner_completion',policy.accept_pending_owner_completion)||
      CASE WHEN coalesce(open_mode,false) THEN '{"mode":"open_mentions"}'::jsonb ELSE '{}'::jsonb END;
    SELECT role INTO actor_role FROM public.room_members WHERE tenant_id=p_tenant_id AND room_id=room_uuid
      AND switch_user_id=identity_row.subject_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF coalesce(open_mode,false) THEN actor_role:='member'; END IF;
    IF jsonb_typeof(p_source->'body') IS DISTINCT FROM 'string' OR length(p_source->>'body')>64000
      OR nullif(p_source->>'occurred_at','') IS NULL OR nullif(p_source->>'switch_message_id','') IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_action_payload'; END IF;
    -- Register exact redacted evidence once; a replay with changed identity/text conflicts.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||'/'||room_uuid::text||'/'||(p_source->>'switch_message_id'),0));
    SELECT * INTO source_row FROM public.commitment_chat_sources WHERE tenant_id=p_tenant_id AND room_id=room_uuid
      AND switch_message_id=p_source->>'switch_message_id';
    IF FOUND THEN
      IF source_row.source_input<>p_source OR source_row.subject_id<>identity_row.subject_id OR
        source_row.policy_snapshot<>policy_json THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='idempotency_conflict'; END IF;
    ELSE
      INSERT INTO public.commitment_chat_sources(tenant_id,room_id,switch_message_id,switch_author_id,external_author_id,
        subject_id,thread_id,external_message_id,workspace_id,channel_id,body,occurred_at,source_input,policy_snapshot)
      VALUES(p_tenant_id,room_uuid,p_source->>'switch_message_id',identity_row.switch_author_id,identity_row.external_author_id,
        identity_row.subject_id,p_source->>'thread_id',p_source->>'external_message_id',p_source->>'workspace_id',p_source->>'channel_id',
        p_source->>'body',(p_source->>'occurred_at')::timestamptz,p_source,
        policy_json)
      RETURNING * INTO source_row;
    END IF;
    SELECT coalesce(jsonb_agg(to_jsonb(candidate)),'[]') INTO candidates FROM (
      SELECT c.* FROM public.commitments c JOIN public.messages m ON m.id=c.message_id AND m.tenant_id=c.tenant_id AND m.room_id=c.room_id
      WHERE c.tenant_id=p_tenant_id AND c.room_id=room_uuid AND c.approval_status<>'rejected'
        AND c.task_status IN ('not_started','in_progress')
        AND (c.owner_switch_user_id=identity_row.subject_id OR (actor_role='admin' AND NOT coalesce(open_mode,false)))
        AND (coalesce(open_mode,false) OR m.thread_id IS NOT DISTINCT FROM source_row.thread_id)
        AND m.occurred_at <= source_row.occurred_at
      ORDER BY c.created_at DESC,c.id LIMIT 21
    ) candidate;
    SELECT coalesce(jsonb_agg(to_jsonb(member)),'[]') INTO members FROM (
      SELECT i.subject_id,i.label,nullif(i.external_author_id,'') external_author_id
      FROM public.commitment_chat_identities i JOIN public.room_members m
        ON m.tenant_id=i.tenant_id AND m.room_id=i.room_id AND m.switch_user_id=i.subject_id
      WHERE i.tenant_id=p_tenant_id AND i.room_id=room_uuid ORDER BY i.subject_id,i.switch_author_id LIMIT 101
    ) member;
    RETURN jsonb_build_object('source',jsonb_build_object('id',source_row.id,
      'scope',jsonb_build_object('tenant_id',p_tenant_id,'room_id',room_uuid),
      'switch_message_id',source_row.switch_message_id,'switch_author_id',source_row.switch_author_id,
      'external_author_id',nullif(source_row.external_author_id,''),'actor',jsonb_build_object('subject_id',source_row.subject_id),
      'external_message_id',source_row.external_message_id,'workspace_id',source_row.workspace_id,'channel_id',source_row.channel_id,
      'body',source_row.body,'occurred_at',source_row.occurred_at,'thread_id',source_row.thread_id,
      'registered_agent_name',p_source->>'registered_agent_name'),
      'role',actor_role,'policy',policy_json,
      'candidates',candidates,'members',CASE WHEN coalesce(open_mode,false) THEN '[]'::jsonb ELSE members END,
      'truncated',jsonb_array_length(candidates)>20 OR (NOT coalesce(open_mode,false) AND jsonb_array_length(members)>100));
END;
$$;

-- Same pure eligibility contract used by the existing reminder outbox migration.
CREATE OR REPLACE FUNCTION public.commitment_reminder(c public.commitments) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
    SELECT jsonb_build_object('eligible',reason='eligible','reason',reason,'due_at',c.due_at,'assignee_id',c.owner_switch_user_id)
    FROM (SELECT CASE WHEN c.approval_status<>'approved' AND NOT (c.approval_status='pending' AND c.owner_accepted_at IS NOT NULL)
      THEN c.approval_status WHEN c.task_status IN ('completed','cancelled') THEN c.task_status
      WHEN c.owner_switch_user_id IS NULL THEN 'unassigned' WHEN c.due_at IS NULL THEN 'no_deadline' ELSE 'eligible' END reason) s;
$$;

-- Creation is its own atomic lifecycle transaction, never arbitrary AI extraction.
CREATE FUNCTION public.create_owner_commitment(p_tenant_id uuid,p_room_id uuid,p_actor_id text,
  p_chat_source_id uuid,p_idempotency_key uuid,p_description text,p_due_at timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE
  s public.commitment_chat_sources; p public.commitment_chat_policies;
  c public.commitments; e public.commitment_action_events; receipt public.commitment_action_receipts;
  msg public.messages; content jsonb; result jsonb; at_time timestamptz:=transaction_timestamp();
BEGIN
  IF p_idempotency_key IS NULL OR p_description IS NULL OR length(btrim(p_description)) NOT BETWEEN 2 AND 2000 THEN
    RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_action_payload'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||'/'||p_room_id::text||'/'||p_actor_id||'/'||p_idempotency_key::text,0));
  PERFORM 1 FROM public.rooms WHERE tenant_id=p_tenant_id AND id=p_room_id AND enabled FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='not_found'; END IF;
  SELECT * INTO s FROM public.commitment_chat_sources WHERE tenant_id=p_tenant_id AND room_id=p_room_id AND id=p_chat_source_id
    AND subject_id=p_actor_id AND policy_snapshot->>'mode'='open_mentions' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='forbidden_action'; END IF;
  SELECT * INTO p FROM public.commitment_chat_policies WHERE tenant_id=p_tenant_id AND room_id=p_room_id AND enabled FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='forbidden_action'; END IF;
  IF s.policy_snapshot<>jsonb_build_object('timezone',p.timezone,'handoff',p.handoff,
    'accept_pending_owner_completion',p.accept_pending_owner_completion,'mode','open_mentions') THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='stale_version'; END IF;
  content:=jsonb_build_object('action','create','chat_source_id',s.id,'description',p_description,'due_at',p_due_at);
  SELECT * INTO receipt FROM public.commitment_action_receipts WHERE tenant_id=p_tenant_id AND room_id=p_room_id
    AND actor_id=p_actor_id AND idempotency_key=p_idempotency_key;
  IF FOUND THEN
    IF receipt.request<>content THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='idempotency_conflict'; END IF;
    RETURN receipt.result;
  END IF;
  IF EXISTS(SELECT 1 FROM public.commitment_action_events WHERE source_evidence_id=s.id) THEN
    RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='idempotency_conflict'; END IF;
  INSERT INTO public.messages(tenant_id,room_id,switch_message_id,switch_author_id,body,occurred_at,thread_id,
    workspace_id,channel_id,external_message_id,external_author_id,extraction_status,extraction_completed_at)
    VALUES(p_tenant_id,p_room_id,s.switch_message_id,s.switch_author_id,s.body,s.occurred_at,s.thread_id,
      s.workspace_id,s.channel_id,s.external_message_id,nullif(s.external_author_id,''),'completed',at_time)
    ON CONFLICT(tenant_id,room_id,switch_message_id) DO NOTHING;
  SELECT * INTO msg FROM public.messages WHERE tenant_id=p_tenant_id AND room_id=p_room_id AND switch_message_id=s.switch_message_id FOR SHARE;
  IF msg.body<>s.body OR msg.switch_author_id IS DISTINCT FROM s.switch_author_id OR msg.occurred_at<>s.occurred_at
    OR msg.thread_id IS DISTINCT FROM s.thread_id THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='idempotency_conflict'; END IF;
  INSERT INTO public.commitments(tenant_id,room_id,message_id,extraction_key,description,owner_switch_user_id,due_at,
    owner_accepted_at,owner_acceptance_source_id)
    VALUES(p_tenant_id,p_room_id,msg.id,'owner-chat:'||s.id,p_description,p_actor_id,p_due_at,at_time,s.id) RETURNING * INTO c;
  INSERT INTO public.memories(tenant_id,room_id,message_id,memory_type,extraction_key,content,active)
    VALUES(p_tenant_id,p_room_id,msg.id,'commitment',c.extraction_key,public.commitment_summary(c),true);
  INSERT INTO public.commitment_action_events(tenant_id,room_id,commitment_id,actor_id,action,occurred_at,idempotency_key,
    expected_version,changed,before,after,backend_actor,source_evidence_id,evidence,outcome)
    VALUES(p_tenant_id,p_room_id,c.id,p_actor_id,'create',at_time,p_idempotency_key,1,true,'{}',public.commitment_snapshot(c),
      'switch-ingestion-worker',s.id,s.body,'applied') RETURNING * INTO e;
  result:=jsonb_build_object('commitment',to_jsonb(c),'reminder',public.commitment_reminder(c),'event',to_jsonb(e),'changed',true);
  INSERT INTO public.commitment_action_receipts VALUES(p_tenant_id,p_room_id,p_actor_id,p_idempotency_key,c.id,content,result);
  RETURN result;
END;
$$;
REVOKE ALL ON FUNCTION public.create_owner_commitment(uuid,uuid,text,uuid,uuid,text,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_owner_commitment(uuid,uuid,text,uuid,uuid,text,timestamptz) TO service_role;

CREATE OR REPLACE FUNCTION public.commitment_summary(c public.commitments) RETURNS text
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
    SELECT 'Commitment: '||c.description||E'\nAssignee: '||coalesce(c.owner_switch_user_id,'unresolved: '||c.owner_name,'unassigned')||
      E'\nApproval: '||c.approval_status||E'\nTask: '||c.task_status||E'\nDue (UTC): '||
      coalesce(to_char(c.due_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'unscheduled')||
      CASE WHEN c.automated_acceptance_at IS NOT NULL THEN E'\nAcceptance: automated owner completion evidence' ELSE '' END||
      CASE WHEN c.owner_accepted_at IS NOT NULL THEN E'\nAcceptance: explicit owner statement' ELSE '' END;
$$;
-- Extend the audit snapshot without losing any existing lifecycle fields.
ALTER FUNCTION public.commitment_snapshot(public.commitments) RENAME TO commitment_snapshot_before_chat;
CREATE FUNCTION public.commitment_snapshot(c public.commitments) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
    SELECT public.commitment_snapshot_before_chat(c)||jsonb_build_object(
      'automated_acceptance_at',c.automated_acceptance_at,'automated_acceptance_source_id',c.automated_acceptance_source_id,
      'owner_accepted_at',c.owner_accepted_at,'owner_acceptance_source_id',c.owner_acceptance_source_id);
$$;

-- Shared transaction engine: unchanged manual rules, explicit internal chat policy.
CREATE FUNCTION public.apply_commitment_action_internal(
    p_tenant_id uuid, p_room_id uuid, p_actor_id text, p_commitment_id uuid,
    p_action text, p_expected_version bigint, p_idempotency_key uuid, p_payload jsonb,
    p_backend_actor text, p_chat_source_id uuid
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE
    c public.commitments; old_c public.commitments; member_role text;
    receipt public.commitment_action_receipts; event public.commitment_action_events;
    request_content jsonb; result jsonb; changed boolean := false;
    action_time timestamptz := transaction_timestamp(); new_due timestamptz;
    chat_source public.commitment_chat_sources; chat_policy public.commitment_chat_policies;
    pending_owner_evidence boolean := false; open_mode boolean := false;
BEGIN
    IF p_action IS NULL OR p_action NOT IN ('approve','reject','start','complete','cancel','reassign','reschedule')
      OR p_expected_version IS NULL OR p_expected_version < 1 OR p_idempotency_key IS NULL
      OR p_actor_id IS NULL OR btrim(p_actor_id) = '' OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
      OR (p_payload - 'reason' - CASE WHEN p_action='reassign' THEN 'assignee_id' WHEN p_action='reschedule' THEN 'due_at' ELSE 'reason' END) <> '{}'
      OR (p_payload->'reason' IS NOT NULL AND jsonb_typeof(p_payload->'reason') NOT IN ('string','null'))
      OR length(p_payload->>'reason') > 1000 THEN
      RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload';
    END IF;
    -- Serialize the same scoped key even if concurrent requests name different commitments.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::text || '/' || p_room_id::text || '/' || p_actor_id || '/' || p_idempotency_key::text,0));
    PERFORM 1 FROM public.rooms WHERE tenant_id=p_tenant_id AND id=p_room_id AND enabled FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404', MESSAGE='not_found'; END IF;
    SELECT role INTO member_role FROM public.room_members WHERE tenant_id=p_tenant_id AND room_id=p_room_id
      AND switch_user_id=p_actor_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404', MESSAGE='not_found'; END IF;
    SELECT * INTO c FROM public.commitments WHERE tenant_id=p_tenant_id AND room_id=p_room_id AND id=p_commitment_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404', MESSAGE='not_found'; END IF;
    IF p_chat_source_id IS NOT NULL THEN
      IF p_backend_actor IS DISTINCT FROM 'switch-ingestion-worker' OR p_action NOT IN ('start','complete','cancel','reassign','reschedule') THEN
        RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='forbidden_action'; END IF;
      SELECT * INTO chat_source FROM public.commitment_chat_sources WHERE id=p_chat_source_id
        AND tenant_id=p_tenant_id AND room_id=p_room_id AND subject_id=p_actor_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='not_found'; END IF;
      open_mode:=coalesce(chat_source.policy_snapshot->>'mode'='open_mentions',false);
      SELECT * INTO chat_policy FROM public.commitment_chat_policies WHERE tenant_id=p_tenant_id AND room_id=p_room_id AND enabled FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='forbidden_action'; END IF;
      IF chat_source.policy_snapshot<>(jsonb_build_object('timezone',chat_policy.timezone,'handoff',chat_policy.handoff,
          'accept_pending_owner_completion',chat_policy.accept_pending_owner_completion)||
          CASE WHEN open_mode THEN '{"mode":"open_mentions"}'::jsonb ELSE '{}'::jsonb END) THEN
        RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='stale_version'; END IF;
      IF NOT open_mode THEN
      PERFORM 1 FROM public.commitment_chat_identities WHERE tenant_id=p_tenant_id AND room_id=p_room_id
        AND switch_author_id=chat_source.switch_author_id AND external_author_id=chat_source.external_author_id AND subject_id=p_actor_id FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='forbidden_action'; END IF;
      END IF;
      PERFORM 1 FROM public.messages WHERE id=c.message_id AND tenant_id=p_tenant_id AND room_id=p_room_id
        AND (open_mode OR thread_id IS NOT DISTINCT FROM chat_source.thread_id) AND occurred_at<=chat_source.occurred_at;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT404',MESSAGE='not_found'; END IF;
      IF (open_mode OR member_role<>'admin') AND (p_action='reassign' OR c.owner_switch_user_id IS DISTINCT FROM p_actor_id) THEN
        RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='forbidden_action'; END IF;
      pending_owner_evidence := p_action='complete' AND c.approval_status='pending'
        AND c.owner_switch_user_id=p_actor_id AND chat_policy.accept_pending_owner_completion;
    ELSE
      IF p_backend_actor IS NOT NULL OR (p_action IN ('approve','reject','cancel','reassign','reschedule') AND member_role NOT IN ('approver','admin'))
        OR (p_action IN ('start','complete') AND c.owner_switch_user_id IS DISTINCT FROM p_actor_id) THEN
        RAISE EXCEPTION USING ERRCODE='PT403', MESSAGE='forbidden_action'; END IF;
    END IF;
    request_content := jsonb_build_object('commitment_id',p_commitment_id,'action',p_action,
                                         'expected_version',p_expected_version,'payload',p_payload);
    IF p_chat_source_id IS NOT NULL THEN request_content:=request_content||jsonb_build_object('chat_source_id',p_chat_source_id); END IF;
    SELECT * INTO receipt FROM public.commitment_action_receipts WHERE tenant_id=p_tenant_id AND room_id=p_room_id
      AND actor_id=p_actor_id AND idempotency_key=p_idempotency_key;
    IF FOUND THEN
      IF receipt.request <> request_content THEN RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='idempotency_conflict'; END IF;
      RETURN receipt.result;
    END IF;
    IF p_chat_source_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.commitment_action_events WHERE source_evidence_id=p_chat_source_id) THEN
      RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='idempotency_conflict'; END IF;
    IF c.version <> p_expected_version THEN RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='stale_version'; END IF;
    IF (c.task_status IN ('completed','cancelled') AND NOT (p_action='complete' AND c.task_status='completed')
        AND NOT (p_action='cancel' AND c.task_status='cancelled'))
      OR (c.approval_status='rejected' AND p_action <> 'reject') THEN
      RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='invalid_transition';
    END IF;
    old_c := c;
    CASE p_action
    WHEN 'approve' THEN
      IF c.approval_status='pending' THEN
        IF c.task_status <> 'not_started' THEN RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='invalid_transition'; END IF;
        c.approval_status:='approved'; c.approval_by_switch_user_id:=p_actor_id; c.approval_at:=action_time;
      END IF;
    WHEN 'reject' THEN
      IF c.approval_status NOT IN ('pending','rejected') OR c.task_status <> 'not_started' THEN
        RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='invalid_transition'; END IF;
      IF c.approval_status='pending' THEN
        c.approval_status:='rejected'; c.approval_by_switch_user_id:=p_actor_id; c.approval_at:=action_time;
      END IF;
    WHEN 'start','complete' THEN
      IF c.approval_status <> 'approved' AND NOT pending_owner_evidence
        AND NOT (open_mode AND c.approval_status='pending' AND c.owner_accepted_at IS NOT NULL)
        THEN RAISE EXCEPTION USING ERRCODE='PT409', MESSAGE='invalid_transition'; END IF;
      IF p_action='start' THEN c.task_status:='in_progress';
      ELSE
        IF c.task_status <> 'completed' THEN
          c.completed_at:=action_time;
          IF pending_owner_evidence THEN c.automated_acceptance_at:=action_time; c.automated_acceptance_source_id:=p_chat_source_id; END IF;
        END IF;
        c.task_status:='completed';
      END IF;
    WHEN 'cancel' THEN
      IF c.task_status <> 'cancelled' THEN c.task_status:='cancelled'; c.cancelled_at:=action_time; END IF;
    WHEN 'reassign' THEN
      IF jsonb_typeof(p_payload->'assignee_id') IS DISTINCT FROM 'string'
        OR length(p_payload->>'assignee_id') NOT BETWEEN 1 AND 512 OR (p_payload->>'assignee_id') ~ '\s' THEN
        RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_assignee'; END IF;
      PERFORM 1 FROM public.room_members WHERE tenant_id=p_tenant_id AND room_id=p_room_id
        AND switch_user_id=p_payload->>'assignee_id' FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_assignee'; END IF;
      IF c.owner_switch_user_id IS DISTINCT FROM p_payload->>'assignee_id' THEN
        c.owner_switch_user_id:=p_payload->>'assignee_id'; c.owner_name:=NULL;
        c.owner_accepted_at:=NULL; c.owner_acceptance_source_id:=NULL;
      END IF;
    WHEN 'reschedule' THEN
      IF NOT (p_payload ? 'due_at') OR jsonb_typeof(p_payload->'due_at') NOT IN ('null','string') THEN
        RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload'; END IF;
      IF p_payload->>'due_at' IS NOT NULL THEN
        IF (p_payload->>'due_at') !~ '^\d{4}-\d{2}-\d{2}[Tt]\d{2}:\d{2}:\d{2}(\.\d+)?([Zz]|[+-]\d{2}:\d{2})$' THEN
          RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload'; END IF;
        BEGIN new_due:=(p_payload->>'due_at')::timestamptz;
        EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
          RAISE EXCEPTION USING ERRCODE='PT422', MESSAGE='invalid_action_payload'; END;
      END IF;
      c.due_at:=new_due;
    END CASE;
    changed := public.commitment_snapshot(c) <> public.commitment_snapshot(old_c);
    IF changed THEN
      UPDATE public.commitments SET approval_status=c.approval_status, approval_by_switch_user_id=c.approval_by_switch_user_id,
        approval_at=c.approval_at, task_status=c.task_status, completed_at=c.completed_at,cancelled_at=c.cancelled_at,
        owner_switch_user_id=c.owner_switch_user_id,owner_name=c.owner_name,due_at=c.due_at,
        automated_acceptance_at=c.automated_acceptance_at,automated_acceptance_source_id=c.automated_acceptance_source_id,
        owner_accepted_at=c.owner_accepted_at,owner_acceptance_source_id=c.owner_acceptance_source_id,
        next_reminder_at=NULL,version=version+1 WHERE id=c.id AND tenant_id=p_tenant_id AND room_id=p_room_id RETURNING * INTO c;
    END IF;
    -- Source message/extraction keys are immutable. Updating text invokes the existing
    -- embedding invalidation trigger, including clearing in-flight worker claims.
    INSERT INTO public.memories(tenant_id,room_id,message_id,memory_type,extraction_key,content,active)
      VALUES(c.tenant_id,c.room_id,c.message_id,'commitment',c.extraction_key,public.commitment_summary(c),
        c.approval_status <> 'rejected' AND c.task_status NOT IN ('completed','cancelled'))
      ON CONFLICT(message_id,memory_type,extraction_key) DO UPDATE SET content=EXCLUDED.content,active=EXCLUDED.active;
    INSERT INTO public.commitment_action_events(tenant_id,room_id,commitment_id,actor_id,action,occurred_at,
      idempotency_key,expected_version,changed,before,after,reason,backend_actor,source_evidence_id,evidence,outcome)
      VALUES(c.tenant_id,c.room_id,c.id,p_actor_id,p_action,action_time,p_idempotency_key,p_expected_version,changed,
        public.commitment_snapshot(old_c),public.commitment_snapshot(c),p_payload->>'reason',p_backend_actor,p_chat_source_id,chat_source.body,CASE WHEN changed THEN 'applied' ELSE 'no_change' END) RETURNING * INTO event;
    result:=jsonb_build_object('commitment',to_jsonb(c),'reminder',public.commitment_reminder(c),'event',to_jsonb(event),'changed',changed);
    INSERT INTO public.commitment_action_receipts VALUES(p_tenant_id,p_room_id,p_actor_id,p_idempotency_key,c.id,request_content,result);
    RETURN result;
END;
$$;

-- Preserve the public/manual RPC signature and its original authorization policy.
CREATE OR REPLACE FUNCTION public.apply_commitment_action(
    p_tenant_id uuid,p_room_id uuid,p_actor_id text,p_commitment_id uuid,
    p_action text,p_expected_version bigint,p_idempotency_key uuid,p_payload jsonb
) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
    SELECT public.apply_commitment_action_internal(p_tenant_id,p_room_id,p_actor_id,p_commitment_id,
        p_action,p_expected_version,p_idempotency_key,p_payload,NULL,NULL);
$$;
CREATE FUNCTION public.apply_commitment_chat_action(
    p_tenant_id uuid,p_room_id uuid,p_actor_id text,p_commitment_id uuid,
    p_action text,p_expected_version bigint,p_idempotency_key uuid,p_payload jsonb,
    p_backend_actor text,p_chat_source_id uuid
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
    IF p_chat_source_id IS NULL OR p_backend_actor IS DISTINCT FROM 'switch-ingestion-worker' THEN
      RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='forbidden_action'; END IF;
    RETURN public.apply_commitment_action_internal(p_tenant_id,p_room_id,p_actor_id,p_commitment_id,
        p_action,p_expected_version,p_idempotency_key,p_payload,p_backend_actor,p_chat_source_id);
END;
$$;
REVOKE ALL ON FUNCTION public.prepare_commitment_chat(uuid,text,jsonb),public.commitment_snapshot(public.commitments),
  public.apply_commitment_action_internal(uuid,uuid,text,uuid,text,bigint,uuid,jsonb,text,uuid),
  public.apply_commitment_chat_action(uuid,uuid,text,uuid,text,bigint,uuid,jsonb,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prepare_commitment_chat(uuid,text,jsonb),public.commitment_snapshot(public.commitments),
  public.apply_commitment_action_internal(uuid,uuid,text,uuid,text,bigint,uuid,jsonb,text,uuid),
  public.apply_commitment_chat_action(uuid,uuid,text,uuid,text,bigint,uuid,jsonb,text,uuid) TO service_role;

-- ============================================================
-- Consolidated from 20261105000300_reminder_outbox.sql
-- ============================================================
-- REVIEW BEFORE HOSTED DEPLOYMENT. Requires lifecycle + chat migrations.
-- Extends existing room policy and reminder_deliveries; does not reset core data.

ALTER TABLE public.commitment_chat_policies
 ADD COLUMN reminders_enabled boolean NOT NULL DEFAULT false,
 ADD COLUMN reminder_policy_version bigint NOT NULL DEFAULT 1 CHECK(reminder_policy_version>0),
 ADD COLUMN reminder_lead_minutes integer NOT NULL DEFAULT 30 CHECK(reminder_lead_minutes BETWEEN 0 AND 10080),
 ADD COLUMN reminder_cadence_minutes integer NOT NULL DEFAULT 1440 CHECK(reminder_cadence_minutes BETWEEN 60 AND 43200),
 ADD COLUMN reminder_max_followups integer NOT NULL DEFAULT 3 CHECK(reminder_max_followups BETWEEN 0 AND 10),
 ADD COLUMN reminder_gap_minutes integer NOT NULL DEFAULT 30 CHECK(reminder_gap_minutes BETWEEN 1 AND 1440),
 ADD COLUMN reminder_room_gap_seconds integer NOT NULL DEFAULT 60 CHECK(reminder_room_gap_seconds BETWEEN 15 AND 3600),
 ADD COLUMN reminder_quiet_start integer NOT NULL DEFAULT 22 CHECK(reminder_quiet_start BETWEEN 0 AND 23),
 ADD COLUMN reminder_quiet_end integer NOT NULL DEFAULT 8 CHECK(reminder_quiet_end BETWEEN 0 AND 23),
 ADD COLUMN reminder_delivery_mode text NOT NULL DEFAULT 'source_thread' CHECK(reminder_delivery_mode IN ('source_thread','room'));
ALTER TABLE public.reminder_deliveries DROP CONSTRAINT reminder_deliveries_status_check;
ALTER TABLE public.reminder_deliveries ADD CONSTRAINT reminder_deliveries_status_check
 CHECK(status IN ('pending','sending','sent','failed','superseded','ambiguous'));
ALTER TABLE public.reminder_deliveries
 ADD COLUMN occurrence_key uuid,
 ADD COLUMN recipient_id text,
 ADD COLUMN commitment_version bigint,
 ADD COLUMN policy_version bigint,
 ADD COLUMN reminder_type text CHECK(reminder_type IN ('upcoming','overdue')),
 ADD COLUMN ordinal integer CHECK(ordinal BETWEEN 0 AND 10),
 ADD COLUMN occurrence_base timestamptz,
 ADD COLUMN dispatch_started_at timestamptz,
 ADD COLUMN superseded_at timestamptz,
 ADD COLUMN notification_body text CHECK(length(notification_body)<=2000);
-- Unversioned unsent legacy rows cannot prove current intent; retain them as history.
UPDATE public.reminder_deliveries SET status='superseded',error_code='legacy_unversioned',superseded_at=now(),claim_token=NULL,lease_until=NULL
 WHERE status<>'sent';
ALTER TABLE public.reminder_deliveries DROP CONSTRAINT reminder_deliveries_commitment_id_scheduled_for_key;
CREATE UNIQUE INDEX reminder_occurrence_unique ON public.reminder_deliveries(occurrence_key) WHERE occurrence_key IS NOT NULL;
CREATE UNIQUE INDEX reminder_logical_unique ON public.reminder_deliveries(commitment_id,commitment_version,policy_version,reminder_type,ordinal)
 WHERE occurrence_key IS NOT NULL;
CREATE UNIQUE INDEX reminder_one_active ON public.reminder_deliveries(commitment_id)
 WHERE occurrence_key IS NOT NULL AND status IN ('pending','sending');
ALTER TABLE public.reminder_deliveries ADD CONSTRAINT reminder_versioned_fields CHECK(occurrence_key IS NULL OR (
 recipient_id IS NOT NULL AND commitment_version>0 AND policy_version>0 AND reminder_type IS NOT NULL
 AND ordinal IS NOT NULL AND occurrence_base IS NOT NULL));
ALTER TABLE public.reminder_deliveries ADD CONSTRAINT reminder_claim_fields CHECK(status<>'sending' OR (claim_token IS NOT NULL AND lease_until IS NOT NULL));

CREATE FUNCTION public.reminder_policy_json(p public.commitment_chat_policies) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT jsonb_build_object('version',p.reminder_policy_version,'enabled',p.reminders_enabled,'timezone',p.timezone,
 'lead_minutes',p.reminder_lead_minutes,'cadence_minutes',p.reminder_cadence_minutes,'max_followups',p.reminder_max_followups,
 'minimum_gap_minutes',p.reminder_gap_minutes,'room_gap_seconds',p.reminder_room_gap_seconds,
 'quiet_start',p.reminder_quiet_start,'quiet_end',p.reminder_quiet_end,'delivery_mode',p.reminder_delivery_mode);
$$;
CREATE FUNCTION public.reminder_quiet(p public.commitment_chat_policies,at_time timestamptz) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT CASE WHEN p.reminder_quiet_start=p.reminder_quiet_end THEN false
 WHEN p.reminder_quiet_start>p.reminder_quiet_end THEN h>=p.reminder_quiet_start OR h<p.reminder_quiet_end
 ELSE h>=p.reminder_quiet_start AND h<p.reminder_quiet_end END
 FROM (SELECT extract(hour FROM at_time AT TIME ZONE p.timezone) h) s;
$$;
CREATE FUNCTION public.reminder_record_eligible(c public.commitments) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT coalesce((public.commitment_reminder(c)->>'eligible')::boolean,false) AND EXISTS(
 SELECT 1 FROM public.rooms r JOIN public.commitment_chat_policies p ON p.tenant_id=r.tenant_id AND p.room_id=r.id
 JOIN public.room_members m ON m.tenant_id=r.tenant_id AND m.room_id=r.id AND m.switch_user_id=c.owner_switch_user_id
 WHERE r.tenant_id=c.tenant_id AND r.id=c.room_id AND r.enabled AND r.platform='discord' AND p.reminders_enabled
 AND p.timezone IS NOT NULL AND EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names z WHERE z.name=p.timezone));
$$;
CREATE FUNCTION public.reminder_delivery_current(d public.reminder_deliveries) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.commitments c JOIN public.commitment_chat_policies p ON p.tenant_id=c.tenant_id AND p.room_id=c.room_id
 WHERE c.tenant_id=d.tenant_id AND c.room_id=d.room_id AND c.id=d.commitment_id AND public.reminder_record_eligible(c)
 AND c.version=d.commitment_version AND p.reminder_policy_version=d.policy_version AND c.owner_switch_user_id=d.recipient_id
 AND (d.reminder_type<>'upcoming' OR c.due_at>now()));
$$;
CREATE FUNCTION public.reminder_history_json(c public.commitments,p public.commitment_chat_policies) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT jsonb_build_object(
 'upcoming_sent',coalesce(bool_or(status='sent' AND reminder_type='upcoming' AND commitment_version=c.version AND policy_version=p.reminder_policy_version),false),
 'overdue_sent',count(*) FILTER(WHERE status='sent' AND reminder_type='overdue' AND commitment_version=c.version AND policy_version=p.reminder_policy_version),
 'last_sent_at',max(sent_at) FILTER(WHERE status='sent'),
 'last_room_sent_at',(SELECT max(room_history.sent_at) FROM public.reminder_deliveries room_history WHERE room_history.tenant_id=c.tenant_id AND room_history.room_id=c.room_id AND room_history.status='sent'),
 'last_overdue_at',max(sent_at) FILTER(WHERE status='sent' AND reminder_type='overdue' AND commitment_version=c.version AND policy_version=p.reminder_policy_version),
 'blocking_delivery',coalesce(bool_or(commitment_version=c.version AND policy_version=p.reminder_policy_version
 AND status IN ('pending','sending','failed','ambiguous') AND
 (status='ambiguous' OR (status='failed' AND next_attempt_at IS NULL) OR reminder_type<>'upcoming' OR c.due_at>now() OR dispatch_started_at IS NOT NULL)),false))
 FROM public.reminder_deliveries WHERE tenant_id=c.tenant_id AND room_id=c.room_id AND commitment_id=c.id;
$$;
CREATE FUNCTION public.reminder_work_json(c public.commitments) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT jsonb_build_object('commitment',to_jsonb(c),'policy',public.reminder_policy_json(p),'history',public.reminder_history_json(c,p),
 'room_enabled',r.enabled,'assignee_is_member',EXISTS(SELECT 1 FROM public.room_members m WHERE m.tenant_id=c.tenant_id AND m.room_id=c.room_id AND m.switch_user_id=c.owner_switch_user_id),
 'switch_room_id',r.switch_room_id,'platform',r.platform,'thread_id',m.thread_id)
 FROM public.rooms r JOIN public.commitment_chat_policies p ON p.tenant_id=r.tenant_id AND p.room_id=r.id
 JOIN public.messages m ON m.id=c.message_id AND m.tenant_id=c.tenant_id AND m.room_id=c.room_id WHERE r.id=c.room_id AND r.tenant_id=c.tenant_id;
$$;
CREATE FUNCTION public.reminder_delivery_json(d public.reminder_deliveries) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT to_jsonb(d)||jsonb_build_object('intention',jsonb_build_object('occurrence_key',d.occurrence_key,'tenant_id',d.tenant_id,
 'room_id',d.room_id,'commitment_id',d.commitment_id,'recipient_id',d.recipient_id,'commitment_version',d.commitment_version,
 'policy_version',d.policy_version,'kind',d.reminder_type,'ordinal',d.ordinal,'occurrence_base',d.occurrence_base,'scheduled_for',d.scheduled_for));
$$;

CREATE FUNCTION public.invalidate_commitment_reminders() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 UPDATE public.reminder_deliveries SET superseded_at=now(),
 status=CASE WHEN status='sending' AND dispatch_started_at IS NOT NULL THEN status ELSE 'superseded' END
 WHERE commitment_id=NEW.id AND tenant_id=NEW.tenant_id AND room_id=NEW.room_id AND status IN ('pending','sending','failed','ambiguous')
 AND commitment_version IS DISTINCT FROM NEW.version;
 RETURN NEW;
END; $$;
CREATE TRIGGER commitments_invalidate_reminders AFTER UPDATE OF version ON public.commitments
 FOR EACH ROW EXECUTE FUNCTION public.invalidate_commitment_reminders();
CREATE FUNCTION public.version_reminder_policy() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF (to_jsonb(NEW)-'lock_marker'-'enabled'-'accept_pending_owner_completion'-'handoff'-'reminder_policy_version')
 IS DISTINCT FROM (to_jsonb(OLD)-'lock_marker'-'enabled'-'accept_pending_owner_completion'-'handoff'-'reminder_policy_version') THEN
   NEW.reminder_policy_version:=OLD.reminder_policy_version+1;
 ELSE NEW.reminder_policy_version:=OLD.reminder_policy_version; END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER reminder_policy_version BEFORE UPDATE ON public.commitment_chat_policies FOR EACH ROW EXECUTE FUNCTION public.version_reminder_policy();
CREATE FUNCTION public.invalidate_policy_reminders() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF NEW.reminder_policy_version<>OLD.reminder_policy_version THEN
 UPDATE public.reminder_deliveries SET superseded_at=now(),
 status=CASE WHEN status='sending' AND dispatch_started_at IS NOT NULL THEN status ELSE 'superseded' END
 WHERE tenant_id=NEW.tenant_id AND room_id=NEW.room_id AND status IN ('pending','sending','failed','ambiguous') AND policy_version<>NEW.reminder_policy_version;
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER reminder_policy_invalidate AFTER UPDATE ON public.commitment_chat_policies FOR EACH ROW EXECUTE FUNCTION public.invalidate_policy_reminders();

CREATE FUNCTION public.read_reminder_work(p_tenant_id uuid,p_switch_room_ids text[],p_limit integer,p_after uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE items jsonb; n integer;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 100 OR coalesce(cardinality(p_switch_room_ids),0) NOT BETWEEN 1 AND 32 THEN
 RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_action_payload'; END IF;
 SELECT coalesce(jsonb_agg(public.reminder_work_json(c) ORDER BY c.id),'[]'),count(*) INTO items,n FROM (
 SELECT c.* FROM public.commitments c JOIN public.rooms r ON r.tenant_id=c.tenant_id AND r.id=c.room_id
 WHERE c.tenant_id=p_tenant_id AND r.switch_room_id=ANY(p_switch_room_ids) AND public.reminder_record_eligible(c)
 AND (p_after IS NULL OR c.id>p_after) ORDER BY c.id LIMIT p_limit) c;
 RETURN jsonb_build_object('items',items,'next_cursor',CASE WHEN n=p_limit THEN items->(n-1)->'commitment'->>'id' END);
END; $$;

CREATE FUNCTION public.persist_reminder_intention(p_tenant_id uuid,p_switch_room_ids text[],p_intention jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE c public.commitments; p public.commitment_chat_policies; h jsonb; inserted uuid;
BEGIN
 SELECT task.* INTO c FROM public.commitments task JOIN public.rooms r ON r.tenant_id=task.tenant_id AND r.id=task.room_id
 WHERE task.tenant_id=p_tenant_id AND task.id=(p_intention->>'commitment_id')::uuid AND task.room_id=(p_intention->>'room_id')::uuid
 AND r.switch_room_id=ANY(p_switch_room_ids) FOR UPDATE OF task;
 IF NOT FOUND OR NOT public.reminder_record_eligible(c) OR p_intention->>'tenant_id'<>p_tenant_id::text THEN RETURN false; END IF;
 SELECT * INTO p FROM public.commitment_chat_policies WHERE tenant_id=c.tenant_id AND room_id=c.room_id FOR SHARE;
 IF c.version<>(p_intention->>'commitment_version')::bigint OR p.reminder_policy_version<>(p_intention->>'policy_version')::bigint
 OR c.owner_switch_user_id<>p_intention->>'recipient_id' THEN RETURN false; END IF;
 -- Expired upcoming intents are replaced by one current overdue intent, not a backlog.
 UPDATE public.reminder_deliveries SET status='superseded',superseded_at=now() WHERE commitment_id=c.id AND tenant_id=c.tenant_id
 AND status IN ('pending','failed') AND reminder_type='upcoming' AND dispatch_started_at IS NULL AND c.due_at<=now();
 h:=public.reminder_history_json(c,p);
 IF (h->>'blocking_delivery')::boolean THEN RETURN false; END IF;
 IF p_intention->>'kind'='upcoming' THEN
   IF c.due_at<=now() OR (h->>'upcoming_sent')::boolean OR (p_intention->>'ordinal')::integer<>0
      OR now()<c.due_at-make_interval(mins=>p.reminder_lead_minutes) THEN RETURN false; END IF;
 ELSIF p_intention->>'kind'='overdue' THEN
   IF c.due_at>now() OR (h->>'overdue_sent')::integer>=p.reminder_max_followups OR
      (h->>'overdue_sent')::integer<>(p_intention->>'ordinal')::integer THEN RETURN false; END IF;
 ELSE RETURN false; END IF;
 IF (p_intention->>'scheduled_for')::timestamptz<now()-interval '5 minutes' OR
    (p_intention->>'occurrence_base')::timestamptz> (p_intention->>'scheduled_for')::timestamptz THEN RETURN false; END IF;
 INSERT INTO public.reminder_deliveries(tenant_id,room_id,commitment_id,scheduled_for,occurrence_key,recipient_id,commitment_version,policy_version,
 reminder_type,ordinal,occurrence_base,next_attempt_at)
 VALUES(c.tenant_id,c.room_id,c.id,(p_intention->>'scheduled_for')::timestamptz,(p_intention->>'occurrence_key')::uuid,c.owner_switch_user_id,c.version,
 p.reminder_policy_version,p_intention->>'kind',(p_intention->>'ordinal')::integer,(p_intention->>'occurrence_base')::timestamptz,(p_intention->>'scheduled_for')::timestamptz)
 ON CONFLICT DO NOTHING RETURNING id INTO inserted;
 RETURN inserted IS NOT NULL;
END; $$;

CREATE FUNCTION public.claim_reminder_deliveries(p_tenant_id uuid,p_switch_room_ids text[],p_limit integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE result jsonb;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_action_payload'; END IF;
 -- Recovery is conservative: an expired claim after durable send-start is uncertain.
 UPDATE public.reminder_deliveries d SET status=CASE WHEN dispatch_started_at IS NOT NULL THEN 'ambiguous' WHEN attempts>=3 THEN 'failed' ELSE 'pending' END,
 error_code=CASE WHEN dispatch_started_at IS NOT NULL THEN 'send_outcome_unknown' WHEN attempts>=3 THEN 'attempts_exhausted' END,
 next_attempt_at=CASE WHEN dispatch_started_at IS NULL AND attempts<3 THEN now() END,
 claim_token=CASE WHEN dispatch_started_at IS NOT NULL THEN claim_token END,lease_until=NULL
 WHERE d.id IN(SELECT d.id FROM public.reminder_deliveries d JOIN public.rooms r ON r.tenant_id=d.tenant_id AND r.id=d.room_id
 WHERE d.tenant_id=p_tenant_id AND r.switch_room_id=ANY(p_switch_room_ids) AND d.status='sending' AND d.lease_until<=now()
 ORDER BY d.id LIMIT 100 FOR UPDATE OF d SKIP LOCKED);
 UPDATE public.reminder_deliveries d SET status='superseded',superseded_at=now()
 WHERE d.id IN(SELECT d.id FROM public.reminder_deliveries d JOIN public.rooms r ON r.tenant_id=d.tenant_id AND r.id=d.room_id
 WHERE d.tenant_id=p_tenant_id AND r.switch_room_id=ANY(p_switch_room_ids) AND d.status IN ('pending','failed')
 AND NOT public.reminder_delivery_current(d) ORDER BY d.id LIMIT 100 FOR UPDATE OF d SKIP LOCKED);
 WITH picked AS(SELECT d.id FROM public.reminder_deliveries d JOIN public.rooms r ON r.tenant_id=d.tenant_id AND r.id=d.room_id
 WHERE d.tenant_id=p_tenant_id AND r.switch_room_id=ANY(p_switch_room_ids) AND d.status IN ('pending','failed')
 AND d.next_attempt_at<=now() AND d.scheduled_for<=now() AND d.attempts<3 AND public.reminder_delivery_current(d)
 ORDER BY d.next_attempt_at,d.id LIMIT p_limit FOR UPDATE OF d SKIP LOCKED), claimed AS(
 UPDATE public.reminder_deliveries d SET status='sending',claim_token=gen_random_uuid(),lease_until=now()+interval '2 minutes'
 FROM picked WHERE d.id=picked.id RETURNING d.*)
 SELECT coalesce(jsonb_agg(public.reminder_delivery_json(claimed)),'[]') INTO result FROM claimed;
 RETURN result;
END; $$;

CREATE FUNCTION public.read_reminder_dispatch(p_tenant_id uuid,p_switch_room_ids text[],p_delivery_id uuid,p_claim_token uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT jsonb_build_object('delivery',public.reminder_delivery_json(d),'work',public.reminder_work_json(c))
 FROM public.reminder_deliveries d JOIN public.commitments c ON c.tenant_id=d.tenant_id AND c.room_id=d.room_id AND c.id=d.commitment_id
 JOIN public.rooms r ON r.id=d.room_id AND r.tenant_id=d.tenant_id
 WHERE d.id=p_delivery_id AND d.tenant_id=p_tenant_id AND r.switch_room_id=ANY(p_switch_room_ids) AND d.claim_token=p_claim_token
 AND d.status='sending' AND d.lease_until>now() AND public.reminder_delivery_current(d);
$$;

CREATE FUNCTION public.defer_reminder_delivery(p_tenant_id uuid,p_switch_room_ids text[],p_delivery_id uuid,p_claim_token uuid,p_until timestamptz)
RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 UPDATE public.reminder_deliveries d SET status=CASE WHEN p_until IS NULL THEN 'superseded' ELSE 'pending' END,
 superseded_at=CASE WHEN p_until IS NULL THEN now() END,next_attempt_at=p_until,claim_token=NULL,lease_until=NULL
 FROM public.rooms r WHERE d.id=p_delivery_id AND d.tenant_id=p_tenant_id AND r.id=d.room_id AND r.tenant_id=d.tenant_id
 AND r.switch_room_id=ANY(p_switch_room_ids) AND d.claim_token=p_claim_token AND d.status='sending' AND d.dispatch_started_at IS NULL;
 RETURN FOUND;
END; $$;

CREATE FUNCTION public.begin_reminder_dispatch(p_tenant_id uuid,p_switch_room_ids text[],p_delivery_id uuid,p_claim_token uuid,p_body text)
RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE d public.reminder_deliveries;c public.commitments;p public.commitment_chat_policies;h jsonb;earliest timestamptz;
BEGIN
 -- Lock task before delivery, matching lifecycle invalidation order. No network inside this transaction.
 SELECT task.* INTO c FROM public.commitments task JOIN public.reminder_deliveries outbox ON outbox.commitment_id=task.id AND outbox.tenant_id=task.tenant_id AND outbox.room_id=task.room_id
 JOIN public.rooms r ON r.id=task.room_id AND r.tenant_id=task.tenant_id WHERE outbox.id=p_delivery_id AND task.tenant_id=p_tenant_id AND r.switch_room_id=ANY(p_switch_room_ids) FOR UPDATE OF task;
 IF NOT FOUND THEN RETURN false; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('reminder-room:'||p_tenant_id::text||'/'||c.room_id::text,0));
 -- Acquire the policy lock before the delivery lock; policy invalidation also locks deliveries.
 SELECT * INTO p FROM public.commitment_chat_policies WHERE tenant_id=c.tenant_id AND room_id=c.room_id FOR SHARE;
 SELECT * INTO d FROM public.reminder_deliveries WHERE id=p_delivery_id AND tenant_id=p_tenant_id FOR UPDATE;
 IF d.status<>'sending' OR d.claim_token IS DISTINCT FROM p_claim_token OR d.lease_until<=now() OR d.dispatch_started_at IS NOT NULL THEN RETURN false; END IF;
 IF p.tenant_id IS NULL OR NOT public.reminder_delivery_current(d) THEN
   UPDATE public.reminder_deliveries SET status='superseded',superseded_at=now() WHERE id=d.id; RETURN false; END IF;
 PERFORM 1 FROM public.rooms WHERE id=c.room_id AND tenant_id=c.tenant_id AND enabled FOR SHARE;
 IF NOT FOUND THEN RETURN false; END IF;
 PERFORM 1 FROM public.room_members WHERE tenant_id=c.tenant_id AND room_id=c.room_id AND switch_user_id=d.recipient_id FOR SHARE;
 IF NOT FOUND THEN RETURN false; END IF;
 h:=public.reminder_history_json(c,p);
 IF (d.reminder_type='upcoming' AND (h->>'upcoming_sent')::boolean) OR (d.reminder_type='overdue' AND
 ((h->>'overdue_sent')::integer<>d.ordinal OR d.ordinal>=p.reminder_max_followups)) THEN
 UPDATE public.reminder_deliveries SET status='superseded',superseded_at=now() WHERE id=d.id; RETURN false; END IF;
 earliest:=greatest(d.scheduled_for,d.occurrence_base,coalesce((h->>'last_sent_at')::timestamptz+make_interval(mins=>p.reminder_gap_minutes),d.occurrence_base));
 earliest:=greatest(earliest,coalesce((h->>'last_room_sent_at')::timestamptz+make_interval(secs=>p.reminder_room_gap_seconds),earliest));
 IF EXISTS(SELECT 1 FROM public.reminder_deliveries other WHERE other.tenant_id=c.tenant_id AND other.room_id=c.room_id
   AND other.id<>d.id AND other.status='sending' AND other.dispatch_started_at IS NOT NULL AND other.lease_until>now()) THEN
   earliest:=greatest(earliest,now()+make_interval(secs=>p.reminder_room_gap_seconds));
 END IF;
 IF d.reminder_type='overdue' AND h->>'last_overdue_at' IS NOT NULL THEN earliest:=greatest(earliest,(h->>'last_overdue_at')::timestamptz+make_interval(mins=>p.reminder_cadence_minutes)); END IF;
 IF earliest>now() OR public.reminder_quiet(p,now()) THEN
   UPDATE public.reminder_deliveries SET status='pending',next_attempt_at=greatest(earliest,now()+interval '1 minute'),claim_token=NULL,lease_until=NULL WHERE id=d.id; RETURN false; END IF;
 IF p_body IS NULL OR length(p_body)>2000 OR d.attempts>=3 THEN RETURN false; END IF;
 UPDATE public.reminder_deliveries SET attempts=attempts+1,dispatch_started_at=now(),notification_body=p_body WHERE id=d.id;
 RETURN true;
END; $$;

CREATE FUNCTION public.finish_reminder_delivery(p_tenant_id uuid,p_switch_room_ids text[],p_delivery_id uuid,p_claim_token uuid,
 p_outcome text,p_message_id text DEFAULT NULL,p_error text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE d public.reminder_deliveries;c public.commitments;p public.commitment_chat_policies;current_intent boolean;n integer;
BEGIN
 SELECT task.* INTO c FROM public.commitments task JOIN public.reminder_deliveries outbox ON outbox.commitment_id=task.id AND outbox.tenant_id=task.tenant_id AND outbox.room_id=task.room_id
 JOIN public.rooms r ON r.id=task.room_id AND r.tenant_id=task.tenant_id WHERE outbox.id=p_delivery_id AND task.tenant_id=p_tenant_id AND r.switch_room_id=ANY(p_switch_room_ids) FOR UPDATE OF task;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO d FROM public.reminder_deliveries WHERE id=p_delivery_id AND tenant_id=p_tenant_id FOR UPDATE;
 IF p_claim_token IS NULL OR d.claim_token IS NULL OR d.claim_token IS DISTINCT FROM p_claim_token
 OR d.status NOT IN ('sending','ambiguous','superseded') OR d.dispatch_started_at IS NULL THEN RETURN false; END IF;
 current_intent:=public.reminder_delivery_current(d) AND d.superseded_at IS NULL;
 SELECT * INTO p FROM public.commitment_chat_policies WHERE tenant_id=c.tenant_id AND room_id=c.room_id;
 IF p_outcome='sent' THEN
   IF nullif(p_message_id,'') IS NULL OR length(p_message_id)>512 THEN RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_action_payload'; END IF;
   UPDATE public.reminder_deliveries SET status='sent',sent_at=now(),switch_reply_message_id=p_message_id,next_attempt_at=NULL,claim_token=NULL,lease_until=NULL,
     error_code=CASE WHEN NOT current_intent THEN 'accepted_after_invalidation' END WHERE id=d.id;
   IF current_intent THEN
     SELECT count(*) INTO n FROM public.reminder_deliveries WHERE commitment_id=c.id AND tenant_id=c.tenant_id AND room_id=c.room_id AND commitment_version=c.version AND policy_version=p.reminder_policy_version AND status='sent' AND reminder_type='overdue';
     UPDATE public.commitments SET last_chased_at=now(),next_reminder_at=CASE WHEN n>=p.reminder_max_followups THEN NULL
       WHEN d.reminder_type='upcoming' THEN greatest(due_at,now()+make_interval(mins=>p.reminder_gap_minutes)) ELSE now()+make_interval(mins=>p.reminder_cadence_minutes) END WHERE id=c.id;
   END IF;
 ELSIF p_outcome IN ('transient','permanent','ambiguous') THEN
   IF p_error IS NULL OR p_error NOT IN ('switch_connect_failed','switch_rate_limited','switch_rejected','send_outcome_unknown','acknowledgement_unavailable','delivery_not_configured') THEN p_error:='send_outcome_unknown'; END IF;
   UPDATE public.reminder_deliveries SET status=CASE WHEN NOT current_intent THEN 'superseded' WHEN p_outcome='ambiguous' THEN 'ambiguous' ELSE 'failed' END,
     next_attempt_at=CASE WHEN current_intent AND p_outcome='transient' AND attempts<3 THEN now()+make_interval(secs=>least(900,30*power(4,attempts-1)::integer)) END,
     error_code=p_error,dispatch_started_at=CASE WHEN p_outcome='transient' THEN NULL ELSE dispatch_started_at END,claim_token=NULL,lease_until=NULL WHERE id=d.id;
 ELSE RAISE EXCEPTION USING ERRCODE='PT422',MESSAGE='invalid_action_payload'; END IF;
 RETURN true;
END; $$;

-- Backend-only functions, with empty search paths. Existing policy provisioning stays privileged.
DO $$ DECLARE f record; BEGIN
 FOR f IN SELECT oid::regprocedure signature FROM pg_catalog.pg_proc WHERE pronamespace='public'::regnamespace
 AND proname IN ('reminder_policy_json','reminder_quiet','reminder_record_eligible','reminder_delivery_current','reminder_history_json',
 'reminder_work_json','reminder_delivery_json','invalidate_commitment_reminders','version_reminder_policy','invalidate_policy_reminders',
 'read_reminder_work','persist_reminder_intention','claim_reminder_deliveries','read_reminder_dispatch','defer_reminder_delivery','begin_reminder_dispatch','finish_reminder_delivery') LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated',f.signature);
 EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.signature);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';

-- ============================================================
-- Consolidated from 20261106000100_simple_commitment_capture.sql
-- ============================================================
-- ADDITIVE, REVIEW BEFORE HOSTED APPLICATION. No tables/columns/reset/history edits.
-- Requires the reviewed four-argument atomic storage RPC and existing owner columns.
-- Lifecycle/chat/reminder migrations are NOT prerequisites for simple capture.

CREATE OR REPLACE FUNCTION public.store_message_extraction(
    p_tenant_id uuid,p_switch_room_id text,p_source jsonb,p_items jsonb,p_capture boolean
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE
    counts jsonb; m public.messages; c public.commitments; item jsonb; owner_id text;
BEGIN
    owner_id:=p_source->>'switch_author_id';
    IF p_capture IS DISTINCT FROM true OR owner_id IS NULL OR length(owner_id) NOT BETWEEN 1 AND 512
      OR owner_id ~ '\s' OR jsonb_typeof(p_items->'commitments') IS DISTINCT FROM 'array'
      OR jsonb_array_length(p_items->'commitments')<>1 THEN
      RAISE EXCEPTION 'invalid_capture' USING ERRCODE='22023'; END IF;
    -- The existing function locks enabled scope/source and performs the entire
    -- extraction. This call and owner initialization share ONE SQL transaction.
    counts:=public.store_message_extraction(p_tenant_id,p_switch_room_id,p_source,p_items);
    SELECT msg.* INTO m FROM public.messages msg JOIN public.rooms r
      ON r.id=msg.room_id AND r.tenant_id=msg.tenant_id
      WHERE msg.tenant_id=p_tenant_id AND r.switch_room_id=p_switch_room_id
        AND msg.switch_message_id=p_source->>'switch_message_id' FOR UPDATE OF msg;
    IF NOT FOUND OR m.switch_author_id IS DISTINCT FROM owner_id OR m.body IS DISTINCT FROM p_source->>'body'
      OR m.occurred_at IS DISTINCT FROM (p_source->>'occurred_at')::timestamptz
      OR m.thread_id IS DISTINCT FROM p_source->>'thread_id' THEN
      RAISE EXCEPTION 'capture_source_conflict' USING ERRCODE='23514'; END IF;
    item:=p_items->'commitments'->0;
    -- A distinct key namespace prevents a replay from claiming a legacy task.
    IF item->>'extraction_key' NOT LIKE 'capture-%' THEN
      RAISE EXCEPTION 'invalid_capture' USING ERRCODE='22023'; END IF;
    SELECT * INTO c FROM public.commitments WHERE tenant_id=p_tenant_id AND room_id=m.room_id
      AND message_id=m.id AND extraction_key=item->>'extraction_key' FOR UPDATE;
    IF NOT FOUND OR c.description IS DISTINCT FROM item->>'description'
      OR c.due_at IS DISTINCT FROM (item->>'due_at')::timestamptz THEN
      RAISE EXCEPTION 'capture_source_conflict' USING ERRCODE='23514'; END IF;
    IF c.owner_switch_user_id IS NULL THEN
      IF c.approval_status<>'pending' OR c.task_status<>'not_started'
        OR coalesce((to_jsonb(c)->>'version')::bigint,1)<>1 THEN
        RAISE EXCEPTION 'capture_source_conflict' USING ERRCODE='23514'; END IF;
      UPDATE public.commitments SET owner_switch_user_id=owner_id,owner_external_id=p_source->>'external_author_id',
        owner_name=p_source->>'author_name' WHERE id=c.id AND tenant_id=p_tenant_id AND room_id=m.room_id;
    ELSIF c.owner_switch_user_id<>owner_id THEN
      -- Preserve later lifecycle reassignment/history; never overwrite it on replay.
      RAISE EXCEPTION 'capture_source_conflict' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.memories WHERE tenant_id=p_tenant_id AND room_id=m.room_id
      AND message_id=m.id AND memory_type='commitment' AND extraction_key=c.extraction_key) THEN
      RAISE EXCEPTION 'capture_summary_missing' USING ERRCODE='23514'; END IF;
    RETURN counts;
END;
$$;
REVOKE ALL ON FUNCTION public.store_message_extraction(uuid,text,jsonb,jsonb,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.store_message_extraction(uuid,text,jsonb,jsonb,boolean) TO service_role;

-- ============================================================
-- Consolidated from 20261106000200_person_profiles.sql
-- ============================================================
-- Additive optional profiles. Review before applying remotely. No historical backfill.

CREATE TABLE public.person_profiles (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    switch_author_id text NOT NULL CHECK(length(switch_author_id) BETWEEN 1 AND 512 AND switch_author_id !~ '\s'),
    display_name text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(tenant_id,room_id,switch_author_id),
    UNIQUE(tenant_id,room_id,id),
    FOREIGN KEY(tenant_id,room_id) REFERENCES public.rooms(tenant_id,id) ON DELETE CASCADE
);
CREATE TABLE public.person_profile_claims (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    extraction_key text NOT NULL,
    attribute text NOT NULL CHECK(attribute IN ('responsibility','skill','preference','timezone')),
    value text NOT NULL CHECK(length(value) BETWEEN 1 AND 256),
    status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','superseded')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(profile_id,extraction_key),
    UNIQUE(tenant_id,room_id,id),
    FOREIGN KEY(tenant_id,room_id,profile_id) REFERENCES public.person_profiles(tenant_id,room_id,id) ON DELETE CASCADE
);
ALTER TABLE public.memories ADD CONSTRAINT profile_memory_scope UNIQUE(tenant_id,room_id,id);
CREATE TABLE public.person_profile_evidence (
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    claim_id uuid NOT NULL,
    message_id uuid NOT NULL,
    memory_id uuid NOT NULL UNIQUE,
    quote text NOT NULL CHECK(length(quote) BETWEEN 1 AND 1000),
    correction boolean NOT NULL,
    occurred_at timestamptz NOT NULL,
    PRIMARY KEY(claim_id,message_id),
    FOREIGN KEY(tenant_id,room_id,claim_id) REFERENCES public.person_profile_claims(tenant_id,room_id,id) ON DELETE CASCADE,
    FOREIGN KEY(tenant_id,room_id,message_id) REFERENCES public.messages(tenant_id,room_id,id) ON DELETE CASCADE,
    FOREIGN KEY(tenant_id,room_id,memory_id) REFERENCES public.memories(tenant_id,room_id,id) ON DELETE CASCADE
);
CREATE INDEX profile_evidence_message ON public.person_profile_evidence(message_id);
CREATE INDEX profile_claim_attribute ON public.person_profile_claims(profile_id,attribute);
CREATE VIEW public.person_profile_context WITH (security_invoker=true) AS
SELECT e.*,c.profile_id,c.attribute,c.value,c.status,p.display_name
FROM public.person_profile_evidence e JOIN public.person_profile_claims c ON c.id=e.claim_id
JOIN public.person_profiles p ON p.id=c.profile_id;
REVOKE ALL ON public.person_profile_context FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.person_profile_context TO service_role;
CREATE TABLE public.profile_extractions (
    message_id uuid PRIMARY KEY REFERENCES public.messages(id) ON DELETE CASCADE,
    request_hash text NOT NULL,
    counts jsonb NOT NULL
);
ALTER TABLE public.person_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.person_profile_claims ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.person_profile_evidence ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profile_extractions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.person_profiles,public.person_profile_claims,public.person_profile_evidence,public.profile_extractions FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.person_profiles,public.person_profile_claims,public.person_profile_evidence,public.profile_extractions TO service_role;

CREATE FUNCTION public.refresh_person_profile(p_profile_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
    PERFORM 1 FROM public.person_profiles WHERE id=p_profile_id FOR UPDATE;
    DELETE FROM public.person_profile_claims c WHERE c.profile_id=p_profile_id
      AND NOT EXISTS(SELECT 1 FROM public.person_profile_evidence e WHERE e.claim_id=c.id);
    UPDATE public.person_profile_claims c SET status=CASE WHEN EXISTS(
      SELECT 1 FROM public.person_profile_evidence e WHERE e.claim_id=c.id
      AND e.occurred_at >= coalesce((SELECT max(x.occurred_at) FROM public.person_profile_evidence x
        JOIN public.person_profile_claims other ON other.id=x.claim_id
        WHERE other.profile_id=c.profile_id AND other.attribute=c.attribute AND x.correction),'-infinity'::timestamptz)
    ) THEN 'active' ELSE 'superseded' END WHERE c.profile_id=p_profile_id;
    UPDATE public.memories m SET active=EXISTS(
      SELECT 1 FROM public.person_profile_evidence e JOIN public.person_profile_claims c ON c.id=e.claim_id
      WHERE e.memory_id=m.id AND c.status='active'
    ) WHERE m.id IN (SELECT e.memory_id FROM public.person_profile_evidence e
      JOIN public.person_profile_claims c ON c.id=e.claim_id WHERE c.profile_id=p_profile_id);
    UPDATE public.person_profiles SET display_name=(SELECT m.author_name FROM public.messages m
      JOIN public.person_profile_evidence e ON e.message_id=m.id
      JOIN public.person_profile_claims c ON c.id=e.claim_id WHERE c.profile_id=p_profile_id
      ORDER BY e.occurred_at DESC,m.id DESC LIMIT 1)
      WHERE id=p_profile_id AND EXISTS(SELECT 1 FROM public.person_profile_claims WHERE profile_id=p_profile_id);
    DELETE FROM public.person_profiles p WHERE p.id=p_profile_id
      AND NOT EXISTS(SELECT 1 FROM public.person_profile_claims c WHERE c.profile_id=p.id);
END;
$$;
CREATE FUNCTION public.refresh_profile_evidence() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE profile_uuid uuid;
BEGIN
    SELECT profile_id INTO profile_uuid FROM public.person_profile_claims
      WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.claim_id ELSE NEW.claim_id END;
    IF profile_uuid IS NOT NULL THEN PERFORM public.refresh_person_profile(profile_uuid); END IF;
    RETURN NULL;
END;
$$;
CREATE TRIGGER refresh_profile_evidence AFTER INSERT OR DELETE ON public.person_profile_evidence
FOR EACH ROW EXECUTE FUNCTION public.refresh_profile_evidence();

-- Distinct name makes missing deployment fail explicitly; no overload ambiguity.
CREATE FUNCTION public.store_profile_message_extraction(
    p_tenant_id uuid,p_switch_room_id text,p_source jsonb,p_items jsonb,p_capture boolean
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE
    room_uuid uuid; message_uuid uuid; profile_uuid uuid; claim_uuid uuid; memory_uuid uuid;
    owner_id text; item jsonb; counts jsonb; saved public.profile_extractions;
    source public.messages; fingerprint text; quote_text text; pattern text; extracted text[];
BEGIN
    SELECT id INTO room_uuid FROM public.rooms WHERE tenant_id=p_tenant_id
      AND switch_room_id=p_switch_room_id AND enabled FOR SHARE;
    IF room_uuid IS NULL THEN RAISE EXCEPTION 'unauthorized_room' USING ERRCODE='42501'; END IF;
    owner_id:=p_source->>'switch_author_id';
    IF owner_id IS NULL OR length(owner_id) NOT BETWEEN 1 AND 512 OR owner_id ~ '\s'
      OR jsonb_typeof(p_items->'profile_facts') IS DISTINCT FROM 'array'
      OR jsonb_array_length(p_items->'profile_facts') NOT BETWEEN 1 AND 10 THEN
      RAISE EXCEPTION 'invalid_profile_source' USING ERRCODE='22023'; END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      p_tenant_id::text||':'||room_uuid::text||':'||owner_id,17));
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      p_tenant_id::text||':'||room_uuid::text||':'||(p_source->>'switch_message_id'),0));
    fingerprint:=md5(jsonb_build_array(p_items,owner_id,p_source->>'body',
      extract(epoch FROM (p_source->>'occurred_at')::timestamptz),p_capture)::text);
    SELECT * INTO source FROM public.messages WHERE tenant_id=p_tenant_id AND room_id=room_uuid
      AND switch_message_id=p_source->>'switch_message_id' FOR UPDATE;
    IF FOUND THEN
      SELECT * INTO saved FROM public.profile_extractions WHERE message_id=source.id;
      IF NOT FOUND OR saved.request_hash<>fingerprint THEN
        RAISE EXCEPTION 'profile_source_conflict' USING ERRCODE='23514'; END IF;
      RETURN saved.counts;
    END IF;
    -- The existing writer and new profile records share this single transaction.
    IF p_capture THEN
      counts:=public.store_message_extraction(p_tenant_id,p_switch_room_id,p_source,p_items,true);
    ELSE
      counts:=public.store_message_extraction(p_tenant_id,p_switch_room_id,p_source,p_items);
    END IF;
    SELECT id INTO STRICT message_uuid FROM public.messages WHERE tenant_id=p_tenant_id AND room_id=room_uuid
      AND switch_message_id=p_source->>'switch_message_id';
    INSERT INTO public.person_profiles(tenant_id,room_id,switch_author_id,display_name)
      VALUES(p_tenant_id,room_uuid,owner_id,p_source->>'author_name')
      ON CONFLICT(tenant_id,room_id,switch_author_id) DO UPDATE SET display_name=public.person_profiles.display_name
      RETURNING id INTO profile_uuid;
    FOR item IN SELECT value FROM jsonb_array_elements(p_items->'profile_facts') LOOP
      quote_text:=regexp_replace(btrim(p_source->>'body',E' \t\n\r'),'^(?:@[\w.-]+|<@!?[A-Za-z0-9_-]+>)[,:]?\s+','');
      IF item->>'evidence' IS DISTINCT FROM btrim(p_source->>'body',E' \t\n\r')
        OR quote_text ~* '\m(if|might|maybe|perhaps|would|could|not|never|quote|said|hypothetically)\M'
        OR jsonb_typeof(item->'correction') IS DISTINCT FROM 'boolean' THEN
        RAISE EXCEPTION 'invalid_profile_evidence' USING ERRCODE='22023'; END IF;
      IF (item->>'correction')::boolean THEN
        pattern:=CASE item->>'attribute' WHEN 'responsibility' THEN 'My responsibility is now '
          WHEN 'skill' THEN 'My specialty is now ' WHEN 'preference' THEN 'My preference is now '
          WHEN 'timezone' THEN 'My timezone is now ' END;
      ELSE
        pattern:=CASE item->>'attribute' WHEN 'responsibility' THEN 'I maintain '
          WHEN 'skill' THEN 'I (?:specialize in|am skilled in) ' WHEN 'preference' THEN 'I prefer '
          WHEN 'timezone' THEN 'My timezone is ' END;
      END IF;
      extracted:=regexp_match(quote_text,'^'||pattern||'([[:alnum:]_ /+#.:-]+?)\.?$','i');
      IF pattern IS NULL OR extracted IS NULL OR btrim(extracted[1]) IS DISTINCT FROM item->>'value'
        OR item->>'extraction_key' NOT LIKE 'profile-%' THEN
        RAISE EXCEPTION 'invalid_profile_evidence' USING ERRCODE='22023'; END IF;
      INSERT INTO public.person_profile_claims(tenant_id,room_id,profile_id,extraction_key,attribute,value)
        VALUES(p_tenant_id,room_uuid,profile_uuid,item->>'extraction_key',item->>'attribute',item->>'value')
        ON CONFLICT(profile_id,extraction_key) DO UPDATE SET extraction_key=public.person_profile_claims.extraction_key
        RETURNING id INTO claim_uuid;
      SELECT id INTO memory_uuid FROM public.memories WHERE tenant_id=p_tenant_id AND room_id=room_uuid
        AND message_id=message_uuid AND memory_type='fact' AND extraction_key=item->>'extraction_key';
      IF memory_uuid IS NULL THEN RAISE EXCEPTION 'profile_summary_missing' USING ERRCODE='23514'; END IF;
      INSERT INTO public.person_profile_evidence(tenant_id,room_id,claim_id,message_id,memory_id,quote,correction,occurred_at)
        VALUES(p_tenant_id,room_uuid,claim_uuid,message_uuid,memory_uuid,item->>'evidence',
          (item->>'correction')::boolean,(p_source->>'occurred_at')::timestamptz);
    END LOOP;
    PERFORM public.refresh_person_profile(profile_uuid);
    INSERT INTO public.profile_extractions VALUES(message_uuid,fingerprint,counts);
    RETURN counts;
END;
$$;
REVOKE ALL ON FUNCTION public.refresh_person_profile(uuid),public.refresh_profile_evidence(),
  public.store_profile_message_extraction(uuid,text,jsonb,jsonb,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_person_profile(uuid),public.refresh_profile_evidence(),
  public.store_profile_message_extraction(uuid,text,jsonb,jsonb,boolean) TO service_role;

-- CONSOLIDATED_FEATURES_END
NOTIFY pgrst,'reload schema';
COMMIT;
